COLLDATA("tadabburur","ur",[[579,"§الإنسان\ndeeds\nجب نذر مانیں تو نذر پوری کریں.\nاپنے آپ پر ترجیح دیتے ہوئے کسی مسلمان کو اپنا پسندیدہ کھانا دیجئے.\nمدرسہ یا کام پر جانے سے قبل صبح کے اذکار پڑھئے، اور مغرب سے پہلے شام کے اذکار پڑھئے.\nguid\nاعمال کو اللہ کےلئے خالص کرنا.\nاہل جنت کی نعمتوں کے بارے میں سوچنا.\nصبر قضاء وقدر پر رضامندی کی علامت ہے.\nrefl\nيُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا ٧\nیعنی اللہ کے لئے جن نذور عہو د کا انہوں نے خود کو پابند کیا انہیں پورا کرتے ہیں۔ لہٰذا جب یہ ان نذور کو پورا کرتے ہیں جو محض ان کے اپنے آپ پر واجب کرنے سے واجب ہوئیں تو وہ اصلی فرائض کو بدرجہ اولیٰ انجام دیتے ہوں گے۔ (السعدی: ۹۰۱)\nاللہ کا نذر کو پوری کرنے والے کی تعریف کس بات پر دلالت کرتی ہے؟\nوَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا ٨ إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا ٩\n(ہم تو صرف اللہ کی رضامندی کے لئے کھلاتے ہیں، نہ تم سے بدلہ چاہتے ہیں ، نہ شکرگزاری) البتہ جس شخص نے فقیروں سے دعا یا مدح کی درخواست کی وہ اس آیت کے ضمن سے خارج ہے۔(ابن تیمیہ: ۶؍۱۴۴)\nکھاناکھلانا اللہ کے لئے خالص کب ہوگا؟\nوَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا ١٢\nیعنی بھوک پر ان کے صبر کرنے اور اپنے آپ پر دوسروں کو ترجیح دینے کی وجہ سے (اللہ تعالیٰ انہیں جنت اور ریشمی لباس عطا فرمائے گا)۔ (ابن جزی: ۲؍۵۱۹)\nاس آیت کی روشنی میں بتائیے کہ وہ کون سی صفت ہے جس کے باعث نیک لوگوں کو جنت حاصل ہوگی؟\nوَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا ١٢ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۖ لَا يَرَوۡنَ فِيهَا شَمۡسٗا وَلَا زَمۡهَرِيرٗا ١٣\nصبر میں نفس کو روکنے اور تھکان وحرارت کی وجہ سے ظاہر وباطن کو جو خشونت لاحق ہوتی ہے انہی وجوہات کی بنا پر اس کا بدلہ جنت ہے جس میں وسعت ہے، ریشم ہے جس میں نرمی اور نعومت ہے، صوفے ہیں جن سے راحت ملتی ہے، سایے ہیں جو گرمی کے منافی ہے۔ (ابن تیمیہ: ۶؍۴۴۵)\nکیوں اہل جنت کی نعمتیں وسعت ونعومت پر مبنی ہوں گے؟\n۞وَيَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤٗا مَّنثُورٗا ١٩\nکم سن بچے خدمت لینے کے لئے سب سے بہتر ہوتے ہیں اس لئے کہ وہ حرکت میں بہت ہلکے اور چلنے پھرنے میں بہت تیز ہوتے ہیں، اور خدمت لینے والا ان کو حکم دینے اور منع کرنے میں حرج نہیں محسوس کرتا۔ (ابن عاشور: ۲۹؍۳۹۷)\nکیوں جنت میں خادمین کم سن بچے ہوں گے؟\nفَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ\nیعنی جس طرح اللہ نے آپ پر وحی نازل فرما کر آپ کی تکریم کی ہے تو آپ بہی اللہ کی قضا وقدر پر صبر کیجئے اور یقین رکھئے کہ وہ آپ کے لئے اپنی بہترین تدبیر اختیار کرے گا۔ (ابن کثیر: ۴؍۴۵۸)\nاللہ کے حکم کے ساتھ صبر کو جوڑنے کا کیا فائدہ ہے؟\nفَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا ٢٤ وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا ٢٥\nیعنی اس کے تقدیری حکم کے لئے صبر کیجئے اور اسے ناراض نہ کیجئے، اور اسکے دینی حکم پر بھی عمل کیجئے اور آپ کو اس سے کوئی روکنے والی چیز روک نہ دے، اور جب صبرآپ (صلی اللہ علیہ وسلم) کو اللہ کی عبادت اور اس کے ذکر کی کثرت میں مدد دیتا ہے تو اللہ نے آپ کو اس کاحکم دیتے ہو فرمایا:(واذکر اسم ربک بکرة وأصيلًا). (السعدی:۹۰۲)\nاللہ کے فیصلے پر صبر کا حکم دینے کے بعد صبح وشام اللہ کے ذکر کرنے کا حکم کیوں دیا گیا؟\nwords\nيَشرَبُ بِهَااس سے لذت اندوز ہوتے ہوئے پیتے ہیں.\nمُستَطِيرًالوگوں میں پھیلا ہوا؛ منتشر.\nقَمطَرِيرًابہت سخت گال چڑھانے والا.\nالأَرَائِكِخوبصورت کپڑوں سے مزین پلنگ.\nزَمهَرِيرًابہت سخت ٹھنڈا.\nوَدَانِيَةًجس کے درخت قریب ہوں ؛ جھکے ہوئے.\nوَذُلِّلَت قُطُوفُهَااور آسان کردیاگیا اس کے پھلوں کا چننا.\nقَوَارِيرَاشیشہ.\nتُسَمَّى سَلسَبِيلًااس کے خوش ہضم ہونے کی وجہ سے سلسبیل نام رکھا گیا."],[580,"§الإنسان ، المرسلات\ndeeds\nآج کی رات کثرت سے تسبیح کریں اور نمازیں پڑھئے.\nسو بار«سُبْحَانَ اللّٰهِ وَبِحَمْدِهِ سُبْحَانَ اللّٰهِ الْعَظِيم» اللہ اپنی حمد سمیت پاک ہے، اللہ عظیم پاک ہے۔ پڑھئے.\nاللہ سے دعا کیجئے کہ وہ آپ کو اپنی رحمت میں داخل کردے.\nguid\nاللہ کے نزدیک مخلوق کا بے حیثیت ہونا جب وہ اس کی نافرمانی کرے.\nہواؤں اور ان کی انواع کے بارے میں غوروفکر کرنا.\nروز قیامت کی ہولناکیوں کی شدت.\nrefl\nوَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا ٢٦\nنماز کو سجدہ سے تعبیر کیا یہ بتلانے کےلئے کہ سجدہ نماز کی سب سے افضل چیز ہے، اور اس میں اشارہ ہے کہ رات خشوع و خضوع کا وقت ہے۔ (البقاعی ۲۱؍۱۵۷)\nنماز کو سجدے سے کیوں تعبیر کیا گیا؟\nوَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا ٢٦\nیعنی اللہ کے لئے بکثرت سجدہ کرو اور یہ عمل صرف کثرت نماز سے ہی ہوسکتا ہے۔ (السعدی: ۹۰۳)\nیہ آیت کریمہ قیام اللیل کی کثرت کی ترغیب پر کس طرح دلالت کرتی ہے؟\nنَّحۡنُ خَلَقۡنَٰهُمۡ وَشَدَدۡنَآ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَآ أَمۡثَٰلَهُمۡ تَبۡدِيلًا ٢٨\nامام سعدی کہتے ہیں: (نحن خلقناہم) یعنی ہم نے ان کوعدم سے وجود بخشا، (وشددنا أسرہم) یعنی ہم نے رگوں، اعصاب اور ظاہری وباطنی قوتوں کے ذریعہ ان کی خلقت کو پختگی بخشی، یہاں تک کہ جسم مکمل اور کامل ہوگیا،اورہر وہ چیز جو وہ چاہتا ہے اس پر قادر ہوگیا۔ جس ذات نے انہیں اس حالت پر وجود بخشا وہ ان کو بدلہ دینے کے لئے ان کی موت کے بعد انہیں لوٹانے پر بھی قادر ہے۔ (السعدی:۹۰۳)\nاس (دنیاوی) زندگی سے قیامت کے دن اٹھائے جانے پر استدلال کی کیا صورت ہے؟\nإِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا ٢٩ وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ٣٠\nاللہ کا فرمان: (فمن شاء اتخذ إلی ربہ سبيلًا) اللہ کی جانب راہ پکڑنے کو ’’جو چاہے‘‘ کی مشیئت پر معلق کیا، اوراس کی قید اللہ کے فرمان: (وما تشاءون إلا أن یشاء اللہ)، میں بندے کی مشیئت کو اللہ تعالیٰ کی مشیئت سے جوڑنا ہے۔ یہ تقدیر کا مسئلہ ہے۔ (الشنقیطی: ۸؍۳۹۹)\nان دونوں آیتوں میں ایمان کے ایک رکن کا ذکر ہے۔ وہ کیا ہے؟\nوَٱلۡمُرۡسَلَٰتِ عُرۡفٗا ١ فَٱلۡعَٰصِفَٰتِ عَصۡفٗا ٢ وَٱلنَّٰشِرَٰتِ نَشۡرٗا ٣ فَٱلۡفَٰرِقَٰتِ فَرۡقٗا ٤ فَٱلۡمُلۡقِيَٰتِ ذِكۡرًا ٥\n(ان آیات میں مختلف چیزوں کی قسمیں کھائی گئی ہیں) ان قسموں کو طول دینے کا مقصد یہ ہے کہ جس چیز کے لئے قسم کھائی گئی ہے اس کی معرفت حاصل کرنے کا سننے والے کو شوق دلایا جائے۔ (ابن عاشور: ۲۹؍۴۱۹)\nاس سورہ میں قسم کو لمبا کیوں کیا گیا؟\nوَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلۡفَصۡلِ ١٤\nفیصلے کا دن اس بات کا مستحق ہے کہ اس کے متعلق سوال کیا جائے اور اس کی عظمت و ہولناکی کو بیان کیا جائے اور ہر وہ چیز جس کی عظمت دوسری چیز سے بیان کی جائے، تو وہ چیز اس دوسری چیز سے عظیم ہوتی ہے (یعنی ہر وہ چیز جس کے ذریعہ فیصلے کے دن کی عظمت و ہولناکی کو بیان کیا گیا ہے، تو فیصلے کا دن ان چیزوں سے زیادہ عظیم ہے) اور مخلوق میں سے کوئی بھی فیصلے کے دن کے علم تک پہنچ نہیں سکتا کیونکہ اس کی کوئی مثال نہیں جس پر اسے قیاس کیاجائے۔ (البقاعی: ۲۱؍۱۷۰)\nآیت میں استفہام کی دلالت کیا ہے؟\nوَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ١٥\nاللہ نے اس (عذاب) کو اس سورہ میں ہر آیت کے بعد تکذیب کرنے والوں کے لئے بار بار دہرایا، اس لئے کہ اس نے اس عذاب کو ان کے درمیان ان کے تکذیب کے بقدر بانٹ دیا ہے، کسی ایک چیزکی تکذیب کرنے والے ہر شخص کے لئے ایک ایسا عذاب ہوگا جو دوسری چیز کی تکذیب کرنے والے سے مختلف ہوگا۔ (القرطبی: ۲۱؍۵۰۱-۵۰۲)\nاس سورت میں تکذیب کرنے والوں کے عذاب کو بار بار کیوں دہرایا گیا ہے؟\nwords\nفَالعَاصِفَاتِ عَصفًاقسم ہے ان سخت ہلاکت خیز تیز آندھیوں کی.\nوَالنَّاشِرَاتِ نَشرًاقسم ہے بادل چلانے پر مامور فرشتوں کی.\nفَالفَارِقَاتِ فَرقًاقسم ہے حق و باطل میں تمیز نازل کرنے والے فرشتوں کی.\nطُمِسَتوہ بجھ جائیں۔ ان کی روشنی ختم ہو گئی.\nفُرِجَتوہ پھٹ گئے.\nنُسِفَتوہ اڑ گئے۔ بکھر گئے.\nأُقِّتَتاجل متعین کی گئی۔ تاکہ امتوں کے درمیان فیصلہ ہو."],[581,"§المرسلات\ndeeds\nقبرستان کی زیارت کیجئے اور اس سے نصیحت وعبرت پکڑئیے.\nاللہ سے دعا کیجئے کہ وہ آپ پر بارش نازل فرمائے.\nتین بار جہنم کے عذاب سے اللہ کی پناہ طلب کیجئے.\nguid\nانسان کی پیدائش پر غور کرنا اور اس بات پر بھی کہ پیدائش(کیسے) قیامت کے دن اٹھائے جانے پر دلالت کرتی ہے.\nکفار کے سائے پر غور کرنا.\nقیامت کے دن نیکی کرنے والوں کے انجام کی فضیلت.\nrefl\nأَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا ٢٥\nزمین زندوں کو اپنی پشت پراور مردوں کو اپنے اندر سمیٹے ہوئے ہے، یہ آیت میت کے دفن کرنے نیز اس کے بالوں اور اس سے زائل کی گئی تمام چیزوں کے دفن پر دلالت کرتی ہے۔(القرطبی: ۲۱؍۵۰۵)\nاس آیت سے کونسا شرعی حکم مستنبط ہوتا ہے؟\nإِنَّهَا تَرۡمِي بِشَرَرٖ كَٱلۡقَصۡرِ ٣٢ كَأَنَّهُۥ جِمَٰلَتٞ صُفۡرٞ ٣٣\n﴿جِمَٰلَتٌ صُفۡرٌ﴾ زرد مائل سیاہی کو کہتے ہیں، یہ جملہ اس بات پر دلالت کرتا ہے کہ جہنم کے شعلے، آگ اور شرارے تاریک ہوں گے، اور یہ کہ جہنم کالی، بد شکل، اور شدید گرم ہے۔ ہم اللہ تعالیٰ سے اس سے سلامتی کا سوال کرتے ہیں۔ (السعدی: ۹۰۵)\nآیت میں تدبر کرنے اورمعنی کو سمجھنے کے بعد جہنم کی آگ کا رنگ بتلائیے؟ اور کیا یہ تاریک ہے یا اس کے اندر کوئی روشنی بھی ہے؟\nفَإِن كَانَ لَكُمۡ كَيۡدٞ فَكِيدُونِ ٣٩\nیہ ان کو عاجز کرنے اور دنیا میں ان کا مکر بیان کرنے اور اس پر انہیں پھٹکار دینے کے لئے ہے۔ (ابن جزی: ۲؍۵۲۵)\nروز قیامت جب کفار عاجز ہوں گے اور بول نہ سکیں گے تو ان سے مکر کس طرح صادر ہوگا؟\nكُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ ٤٣\nاس کلام میں صراحت ہے کہ دنیا میں ان کا عمل آخرت میں جنت کی نعمتوں سے فائدہ اٹھانے کا سبب ہوگا، جبکہ حدیث میں ہے: «لَنْ يَّدْخَلَ أَحَدٌ مِنْكُمْ الْجَنَّةَ بِعَمَلِهِ» تم میں سے کوئی بھی جنت میں اپنے عمل کے بدلے ہرگز نہیں داخل ہوگا۔(بخاری و مسلم) دونوں نصوص میں کوئی تعارض نہیں ہے، اس لئے کہ داخل ہونا اللہ کے فضل سے ہوگا، پھر داخل ہونے کے بعد اعمال کے سبب وارث بنایا جائے گا، درجات ہوں گے اور فائدہ اٹھانا ہوگا۔ جنت میں داخل ہو نے کے واسطے اللہ کے فضل میں تمام لوگ شریک ہوں گے،لیکن داخل ہونے کے بعد اعمال کے سبب درجات میں تفاوت ہوگا۔ (الشنقیطی: ۸؍۴۰۴)\nاعمال اور جنت کے دخول کے درمیان کیا تعلق ہے؟\nكُلُواْ وَتَمَتَّعُواْ قَلِيلًا إِنَّكُم مُّجۡرِمُونَ ٤٦\nاس میں دلالت ہے کہ ہر مجرم کا انجام چنددن فائدہ اٹھانا ہےاور پھر عذاب وہلاکت میں ہمیشہ باقی رہنا ہے۔ (الألوسی: ۱۵؍۱۹۷)\nمجرمین کے لئے دنیا میں فائدہ اٹھانے اور کھانے کا حکم کس بات پر دلالت کرتا ہے؟\nوَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ ٤٨\n(جب ان سے کہا جاتا ہے کہ) اللہ عز وجل کی وحی قبول کرتے ہوئے اس کی اطاعت کرو اور اس کے دین کی اتباع کرتے ہوئے اسی کے لئے خشوع وخضوع اختیار کرو اور اس تکبر ونخوت کو اتار پھینکو۔ (لَا يَرْكَعُوْنَ) تو وہ نہ خشوع اختیار کرتے ہیں، نہ اسے قبول کرتے ہیں بلکہ اپنے تکبر پر مصر رہتے ہیں۔ (الألوسی: ۱۵؍۱۹۷)\nرکوع کاحکم اور مشرکین کا اس کوقبول نہ کرنے کی دلالت کیا ہے؟\nوَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ ٤٨ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ٤٩\nان کا ایک جرم یہ بہی ہے کہ جب انہیں نماز کا حکم دیا جاتا ہے جو عبادات میں افضل و اشرف ہے اور ان سے کہا جاتا کہ رکوع کرو تو وہ اس حکم سے رو گردانی کرتے ہیں ۔ اس سے بڑا جرم اور کیا ہوسکتا ہے؟ اس سے بڑی تکذیب اور کیا ہوسکتی ہے؟ (السعدی: ۹۰۵)\nاس آیت میں تدبر کیجئے اور نماز کا مقام و مرتبہ بیان کیجئے؟\nwords\nمَاءٍ مَهِينٍضعیف و حقیر پانی ؛ مراد نطفہ ہے.\nقَرَارٍ مَكِينٍایک مضبوط جگہ / جائے قرار.\nقَدَرٍوقت متعین.\nكِفَاتًااپنے اندر سمیٹنے والی ؛زمین جو زندوں اور مردوں کو سمیٹ لیتی ہے.\nرَوَاسِيَاونچے اونچے پہاڑ.\nفُرَاتًامیٹھا ؛ خوش ہضم.\nظِلٍّجہنم کا دھواں.\nذِي ثَلاَثِ شُعَبٍجس سے تین شاخیں نکلتی ہوں.\nلاَ ظَلِيلٍنہ کوئی سایہ ہوگا؛اس دن کی گرمی سے بچنے کے لیے.\nكَالقَصرِجیسے کوئی محل / بڑی اور اونچی عمارت.\nجِمَالَةٌ صُفرٌکالے شریر اونٹ جن کی رنگت پیلے رنگ کی طرف مائل ہوتی ہے."],[582,"§النبإ\ndeeds\nآج رات جلدی سوئیے اور پھرجلدی سونے کے کوئی دوفائدے بتائیے.\nتین بار جہنم سے اللہ کی پناہ مانگئے.\nاپنے کئے ہوئےکسی گناہ کو یادکیجئے اور اللہ سے معافی مانگئے.\nguid\nاللہ تعالیٰ کی اپنی مخلوق پر بہت سی نعمتیں ہیں جو اس کا بکثرت شکر ادا کرنے کا تقاضہ کرتی ہیں.\nجہنمی جب تک اللہ تعالیٰ کا یہ فرمان نہیں سن لیں گے اس وقت تک وہ جنت کی ٹھنڈک اور پانی کی آس لگائے ہوں گے.\nقیامت کے دن ہونے والے حساب پر ایمان نہ رکھنا یا اس سے غفلت برتنا گناہوں کی کثرت کا سبب ہے.\nrefl\nعَمَّ يَتَسَآءَلُونَ ١ عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ ٢\nاللہ تعالیٰ نے پہلے کافروں کے سوال پوچھنے کا ذکر کیا اور پھرخود ہی اس کا جواب دیا اور فرمایا: (عن النبأ العظیم). (بڑی خبر کے بارے میں)تو اس طرح اللہ نے لوگوں کے دماغ اپنی بات کی طرف کھینچنے اور انہیں اپنی طرف متوجہ کرنے کے لئے سوال پوچھنے کااسلوب اپنایااور پھر اسے واضح کر دیا۔ اس سے معلو م ہوتا ہے کہ جس چیزکی بابت سوال ہورہا ہے وہ بہت ہی اہم ہے۔ توگویا اس طرح کہا گیا: وہ لوگ جس چیز کی بابت سوال کررہے ہیں، کیا میں تمہیں اس کے بارے میں بتاؤں ؟اور پھر بطور جواب کہا گیا: (عن النبأ العظیم). بڑی خبر کے بارے میں۔(الشوکانی: ۵؍۳۶۳)\nسورت کے شروع میں سوال پوچھنے کا اسلوب کیوں اختیار کیا گیا؟\nٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ ٣\nموصول کے صلہ کی شکل میں جملہ اسمیہ لایا گیا اور (الَّذِيْ یَخْتَلِفُوْنَ فِيْهِ )کے بجائے (الذین ہم فیہ مختلفون) کہا گیا۔جملہ اسمیہ لانے سے یہ سمجھ میں آتا ہے کہ اس خبر کولے کر وہ ہمیشہ اختلاف میں ہی پڑے رہیں گے اور اس سے باہر نہیں آپائیں گے۔وہ اس طرح کہ جملہ اسمیہ اپنے معنی کی ہمیشگی پر دلالت کرتاہے۔ (ابن عاشور: ۳۰؍۱۱)\nموصول کے صلہ کے بطور جملہ فعلیہ نہ لاتے ہوئے جملہ اسمیہ لانے کا کیا فائدہ ہے؟\nأَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا ٦ وَٱلۡجِبَالَ أَوۡتَادٗا ٧ وَخَلَقۡنَٰكُمۡ أَزۡوَٰجٗا ٨ وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا ٩ وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا ١٠ وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا ١١ وَبَنَيۡنَا فَوۡقَكُمۡ سَبۡعٗا شِدَادٗا ١٢ وَجَعَلۡنَا سِرَاجٗا وَهَّاجٗا ١٣ وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا ١٤\nیہاں اللہ تعالیٰ نے ان مخلوقات کا ذکر بطور توقیف کیا ہے یعنی اپنے موقف کی ایسی مضبوط دلیل دی جائے کہ مخالف کی ہر دلیل ختم ہوجائے۔وجہ یہ ہے کہ کفار جو دوبارہ زندہ کئے جانے کا انکار کرتے ہیں ان پر حجت قائم ہوسکے گویا وہ کہہ رہا ہے: بیشک جو معبود ان بڑی بڑی مخلوقات کو پیدا کرنے پر قادر ہے وہ مردوں کو دوبارہ زندہ کرنے پر بدرجہ اَولیٰ قادر ہے۔(ابن جُزی: ۱؍۲۵۴۱)\nاللہ نے ان آیات میں ایک خاص سبب سے ان مخلوقات کا ذکر کیا ہے۔وہ سبب کیا ہے؟\nوَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا ٩\nنیند تمہارے لئے راحت اور تمہاری ان مصروفیات پر روک لگانے والی ہے جو زیادہ ہوجائیں تو تم نقصان میں پڑسکتے ہو اس لئے اللہ تعالیٰ نے رات اور نیند کو بنایا تاکہ وہ لوگوں پر چھاکر انہیں نقصاندہ حرکات سے بچاسکیں اور انہیں نفع بخش راحت مل سکے۔(السعدی:۹۰۶)\nنیند اللہ کی ایسی نعمت کیوں ہے کہ اللہ نے بندوں پر اس کا احسان جتایا ہے؟\nإِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادٗا ٢١\nکوئی بھی شخص جہنم پر سے گزرے بغیر جنت میں نہیں جاسکے گا، اگر اس کے پاس آگے بڑھنے کا کوئی جواز ہوگا تو نجات پائیگا ورنہ اسے روک دیا جائیگا۔(ابن کثیر: ۴؍۴۶۴)\nجہنم کو کمین گاہ (گھات لگانے کی جگہ) بنائے جانے سے کیا سمجھ میں آتا ہے؟\nوَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ كِتَٰبٗا ٢٩\nہر چیز چاہے کم ہو یا زیادہ اللہ نے اسے لوح محفوظ میں لکھ رکھا ہے لہٰذا مجرمین یقین رکھیں کہ انہیں ان کے کئے ہوئے گناہوں کی ہی سزا ملے گی،اللہ ان کے اعمال میں سے کچھ ضائع کریگا اور نہ ہی رتی بھر جرم کو بھولے گا۔ (السعدی:؍۹۰۷)\nبندوں کے اعمال لکھے جانے میں کیا حکمت ہے؟\nفَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا ٣٠\nعبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ:جہنمیوں کے لئے اس سے زیادہ دھمکی بھری کوئی آیت نازل نہیں ہوئی فرمایا کہ: (فذوقوا فلن نزیدکم إلا عذابًا)؛ ان کے عذاب میں ہمیشہ اضافہ ہی ہوتا رہے گا۔ (الطبری: ۲۴؍۱۶۹)\nقرآن کے اندر جہنمیوں کے لئے سب سے سخت آیت کون سی ہے، اور کیوں؟\nwords\nسُبَاتًاتمہارے بدن کے لیے راحت / کام کاج کو منقطع کرنے والی.\nسِرَاجًا وَهَّاجًاروشن (چراغ )سورج.\nالمُعصِرَاتِبارش برسانے والے بادل.\nثَجَّاجًابکثرت برسنے والے.\nوَجَنَّاتٍ أَلفَافًالپٹے ہوئے باغ/ گھنے درخت.\nمِيقَاتًاوقت مقرر۔ مخلوق کے درمیان فیصلہ کرنے کے لیے.\nمِرصَادًاگھات لگائے.\nأَحقَابًازمانہ نہ منقطع ہونے والا.\nوَغَسَّاقًااور جنہمیوں کی پیپ.\nوِفَاقًاعادلانہ ؛ پورا پورا؛ ان کے اعمال کے مطابق."],[583,"§النبإ ، النازعات\ndeeds\nروزانہ کے اعمال میں کوئی ایسے تین اعمال کیجئے جو تقویٰ پر دلالت کریں مثلاً روزہ رکھنا،اللہ تعالیٰ سے شرماتے ہوئے رہنا اور اس کی سزا سے بچنے کے لیے گناہ سے باز رہنا، صدقہ دینا،لوگوں کے ساتھ اچھا سلوک کرنا او ر کسی مسلمان کو خوشی پہنچانا.\nبرے خاتمہ سے اللہ کی پناہ مانگئے.\nاللہ تعالیٰ سے موت کےوقت حسن خاتمہ کی دعا مانگئےاور اللہ کے فرمان ، کو یاد کیجئے.\nguid\nیہاں تقویٰ کی فضیلت نیز اللہ نے متقیوں کے لئے کیسے انعامات تیار رکھے ہیں اس کا بیان ہے.\nاللہ تعالیٰ کی کما حقہ تعظیم کی جائے.\nقیامت قریب ہے اور یقینا ہر آنے والی چیز قریب ہی ہے.\nrefl\nلَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّٰبٗا ٣٥\nاللہ تعالیٰ کا یہ فرمان (لا یسمعون فیہا لغوًا ولا کذابا) اس فرمان کے ہم معنی ہے: ﴿لَّا لَغۡوٌ فِيهَا وَلَا تَأۡثِيمٌ﴾ [الطور: ۲۳]؛ (سورۂ طور:۳۲)مفہوم یہ ہے کہ: جنت میں بےفائدہ لغو،جھوٹ اورگناہ کی باتیں نہیں ہوں گی۔وہ سلامتی کا گھر ہے اور اس کی ہر چیز نقص اور عیب سے پاک ہے۔(ابن کثیر: ۴؍۴۶۵)\nآیت میں جنت کی ایک معنوی نعمت کا تذکرہ ہے۔اس کی وضاحت کیجئے.\nلَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّٰبٗا ٣٥\nجہنمیوں کے تمام حواس شدید قسم کے عذاب میں گرفتار ہوں گے جیسے کہ سخت ترین آگ سے جلنا،گرم کھولتا ہوا پانی اور جہنمیوں کے زخموں سے بہتی ہوئی گندگی پینا وغیرہ تاکہ ان کے ظاہر کی طرح ان کے اندرون کو بھی مبتلائے عذاب کیا جائے تو اس کے مقابلہ میں جنتیوں سے ہلکی تکلیف کی بھی نفی کردی گئی اور وہ ہے ناپسندیدہ بات کو سننا۔(ابن عاشور: ۳۰؍۴۶)\nجنتیوں کے بے فائدہ اور جھوٹ بات کو سننے کی نفی کی گئی ہے۔اس کی اس سے پہلے والی آیتوں سے کیا مناسبت ہے؟\nإِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا ٤٠\nکافریہ جملہ کہ ’’کاش!میں مٹی ہوتا‘‘ قیامت کے دن اس وقت کہے گاجب توبہ قبول نہیں ہوگی اور نہ اس کا کوئی بھلا کام فائدہ مند ہوگا۔ جبکہ جو لوگ دنیا میں اس طرح کی بات کہتے ہیں تو یہ اللہ کے ڈر سے کہتے ہیں چنانچہ انہیں تو اللہ سے ڈرنے پر ثواب ملے گا۔مریم نے بھی کہا تھا: ﴿يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا﴾ [مریم: ۲۳]؛ ہائے کاش! میں اس سے پہلے ہی مرچکی ہوتی اور بھولی بسری گمنام ہوچکی ہوتی۔ اور یہ بات قیامت کے دن موت کی تمنا کی طرح نہیں تھی۔ (ابن تیمیہ: ۶؍۴۵۶)\nدنیا میں کسی گناہ پر شرمندہ ہونے اور آخرت میں شرمندہ ہونے کے درمیان کیا فرق ہے؟\nإِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا ٤٠\nابوہریرہ اور ابن عمر رضی اللہ عنہم سے روایت ہے کہ: اللہ تعالیٰ قیامت کے دن جانوروں کو ایک دوسرے سے بدلہ دلوائیگا اور پھر ان سے کہے گا:’’کُونِی تُرَابًا‘‘مٹی ہوجا۔ تو وہ مٹی بن جائیں گے،اس وقت کافر بھی یہ تمنا کریگا۔ معلوم ہوا کہ وہ دن بہت ہی عظمت والا ہے اور یہ ہوکر رہے گا۔ (البقاعی: ۲۱؍۲۱۶)\nکافر کب مٹی بنادیے جانے کی تمنا کریگا اور کیوں؟\nوَٱلنَّٰشِطَٰتِ نَشۡطٗا ٢\nبعض سلف نے کہا: فرشتے مومن کی روح بہت ہی آہستگی سے کھینچتے ہیں،پھر تھوڑی دیر رک جاتے ہیں تاکہ اسے آرام مل سکے،اس کے بعد نہایت نرمی اور مہربانی سے جسم سے نکالتے ہیں جیسے کوئی ڈوبنے سے بچنے کے لئے پانی میں آہستہ آہستہ ہاتھ پیر چلاتا او ر تیرتاہے تو فرشتے بھی مومن کی روح ایسے ہی نرمی سے نکالتے ہیں تاکہ اسے تکلیف نہ ہو۔ (الألوسی: ۳۰؍۲۳)\nفرشتے مومن کی روح کیسے قبض کرتے ہیں اور کیوں؟\nقُلُوبٞ يَوۡمَئِذٖ وَاجِفَةٌ ٨ أَبۡصَٰرُهَا خَٰشِعَةٞ ٩\n(أبصارہا خاشعة): یہ ذلت اور خوف کی طرف اشارہ ہے۔(ابن جزی:۱؍۲۵۴۵)\nاس آیت میں نگاہوں کے جھکے ہونے سے کیا مراد ہے؟\nهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ ١٥\nاس کے ذریعہ نبی صلی اللہ علیہ وسلم کو تسلی دینا مقصود ہے کہ فرعون آپ کے زمانہ کے کافروں سے بہت زیادہ طاقتور تھا،ہم نے اسے پکڑ لیا تو یہی انجام ان کا بھی ہوگا۔(القرطبی: ۲۲؍۵۳)\nاللہ نے نبی صلی اللہ علیہ وسلم سے موسیٰ علیہ السلام اور فرعون کا قصہ کیوں بیان کیا ہے؟\nwords\nمَفَازًاوہ جگہ جس کو حاصل کرنے میں کامیاب ہوں ؛ مراد جنت.\nوَكَوَاعِبَنو عمر ؛ کم عمر.\nدِهَاقًاشراب سے بھرا ہوا.\nمَآبًانیک اعمال پر ملنے والا ٹھکانا.\nوَالنَّاشِطَاتِقسم ہے نرمی سے روح نکالنے والے فرشتوں کی.\nوَالسَّابِحَاتِان ملائکہ کی قسم جو آسمان سے تیرتے ہوئے نازل ہوتے ہیں.\nفَالسَّابِقَاتِان ملائکہ کی قسم جو انبیاء کی طرف وحی میں شیاطین پر سبقت لے جاتے ہیں.\nتَتبَعُهَا الرَّادِفَةُاس کے بعد ایک بار صور پھونکا جائے گا؛ بعث کے لیے."],[584,"§النازعات\ndeeds\nغیرمسلمین کو حکیمانہ اسلوب میں اسلام کی دعوت دی جائے.\nایسے نیک اعمال انجام دیجئے جنہیں آپ قیامت کے دن یاد رکھناچاہتے ہیں.\nسونے سے پہلے اپنا محاسبہ کرلیا کیجئے.\nguid\nدعوت وتبلیع میں بہترین اسلوب اور نرمی اختیار کرنی چاہئے.\nکوئی کتنا ہی سرکش کیو ں نہ ہو اسے دین کی دعوت دی جائیگی.\nہمیشہ اللہ کی نگرانی کا خیال رکھنا بہت اہم ہے.\nrefl\nفَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ ١٨\nدراصل اسے اس بات پر ابھارنا ہے کہ وہ گمراہ کن عقیدے سے باز آجائے جو نفس کو خبیث بناد یتا ہے اوراس کے بعد وہ نصیحت کرنے والے کی نصیحت قبول کرلے جس میں خیر ہی خیر ہے۔(ابن عاشور: ۳۰؍۷۷)\nموسیٰ علیہ السلام نے فرعون کو دعوت کی ابتداء تزکیہ سے کیوں کیا، اس کا کیا فائدہ ہے؟\nوَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ ١٩\nرہنمائی کے بعد اللہ کے ڈر کا ذکرکرنا اس جانب اشارہ ہے کہ اللہ کو جانے بغیر اس سے ڈرنا ممکن نہیں ہے۔اللہ تعالیٰ کا فرمان ہے : ﴿يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْ﴾ (سورۂ فاطر: ۲۸) یقینا اللہ کو جاننے والے بندے ہی اس سے کماحقہ ڈرتے ہیں۔ اور یہ ڈر ایسا ہے جس کے موجود ہوتےہوئے گناہ اور کوتاہی نہیں ہوتی۔ (ابن عاشور: ۳۰؍۷۷)\nآیت ِ کریمہ میں خشیت کا ذکر ہدایت کے بعد کیوں آیا؟\nإِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّمَن يَخۡشَىٰٓ ٢٦\nجو اللہ سے ڈرتا ہے وہی درحقیقت آیات اور نصیحتوں سے فائدہ اٹھاتا ہے۔ ایسا شخص جب فرعون کو ملنے والی سزا کو جانے گا تو یقین کر لیگا کہ جو بھی تکبر کریگا، گناہ کریگا اور اللہ کے مقابلہ میں آئیگا اللہ اسے دنیا اور آخرت میں عذاب میں مبتلا کردیگا۔اس کے برخلاف جس کے دل میں اللہ کا ڈر نہ ہو تو کسی بھی طرح کی آیت پر وہ ایمان نہیں لائے گا۔ (السعدی:۹۰۹)\nقرآنی وعظ ونصیحت سے کون فائدہ اٹھاتا ہے اور کون نہیں؟\nءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ بَنَىٰهَا ٢٧ رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا ٢٨ وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا ٢٩ وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ ٣٠ أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا ٣١ وَٱلۡجِبَالَ أَرۡسَىٰهَا ٣٢ مَتَٰعٗا لَّكُمۡ وَ لِأَنۡعَٰمِكُمۡ ٣٣\nجو لوگ قیامت کے دن دوبارہ زندہ کئے جانے اور روحوں کے جسموں میں لوٹائے جانے کا انکار کرتے ہیں اللہ تعالیٰ واضح دلیل کے ساتھ ان سے دوٹوک الفاظ میں کہتاہے کہ اے انسانو! تمہیں پیدا کرنا زیادہ مشکل ہے یا آسمان وزمین کو پیدا کرنا؟! جس ذات نے بڑے بڑے آسمانوں اور ان میں موجود ستاروں اور سیاروں کو پیدا کیا، ٹھوس مٹی والی زمین پیدا کی اور اس میں مخلوق کی ضرورت اور فائدے کی ہر چیز پیدا کی یقیناً وہ مکلف مخلوق کو دوبارہ زندہ کریگا اور انہیں ان کے اعمال کا بدلہ دیگا۔اب جس نے نیکیاں کی ہوں گی اس کا بدلہ اچھا ہوگا اور جو گناہ گار ہوگا تو وہ اپنے آپ کو ہی کوسےگا۔اسی مقصد کی خاطر اللہ تعالیٰ نے ان نعمتوں کے تذکرہ کے بعد قیامت اور جزاء وسزا کا ذکر کیا ہے۔ (السعدی:۹۰۹)\nاللہ تعالیٰ نے جو بڑی نشانیاں ذکر کی ہیں وہ کس بات پر دلالت کرتی ہیں؟ اور ان کے بعد قیامت او ر جزا وسزا کے ذکر کا کیا مقصدہے؟\nوَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ ٣٦\nمعلوم یہی ہوتا ہے کہ ہر شخص جہنم کو دیکھے گا۔مومن اسے دیکھے گا تو اسے اپنے اوپر اللہ کے احسان کا اندازہ ہوگا کہ اللہ نے اسے جہنم سے بچاکر کتنا بڑا کرم کیا ہے اور کافر دیکھے گا تو اس کے غم اور حسرت میں مزید اضافہ ہی ہوگا۔ (الشوکانی: ۵؍۳۸۰)\nکیا جہنم کو مومن اور کافر دونوں دیکھیں گے؟ یا صرف کافر دیکھیں گے؟ اور کیوں؟\nوَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ ٤٠ فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ ٤١\n(الہوی) : کا اصل معنی ہوتا ہے میلان،رجحان،مگر جو معنیٰ مشہور ہے وہ ہے: ’’شہوت کی طرف جھکاؤ‘‘۔ علامہ راغب اصبہانی کے بقول: خواہش ِنفس کو (الہوی) کہنے کی وجہ یہ ہے کہ وہ خواہش پرست کو دنیا میں واہیات امور میں گرادیتی ہے اور آخرت میں جہنم میں گرادے گی؛اسی وجہ سے نفسانی خواہشات کی مخالفت کرنے والا قابل تعریف ہے۔ بعض حکماء کا کہنا ہے کہ: اگر آپ کسی مسئلہ میں حق جاننا چاہیں تو دیکھئے کہ آپ کا نفس کس طرف مائل ہے بس آپ اس کے مخالف پہلو کو چن لیجئے۔ فُضیل بن عیاض رحمہ اللہ نے کہا: نفسانی خواہشات کی مخالفت افضل ترین عمل ہے۔ (الألوسی: ۳؍۳۶)\nنفسانی خواہشات کو (الہوی) نام دینے کی کیا وجہ ہے؟\nإِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا ٤٥\nنبی صلی اللہ علیہ وسلم کی بعثت کا مقصد قیامت سے خبردار کرنا ہے،اس کے متعینہ وقت کی اطلاع دینا نہیں اور چونکہ جو قیامت سے ڈریگا وہی اس ڈراوے سے فائدہ اٹھائے گا اسی لئے ڈرنے والے کا ذکر کیاگیا ہے۔ (ابن جُزی: ۲؍۵۳۵)\nخبردار کرنا کسے فائدہ پہنچاتا ہے؟\nwords\nتَزَكَّىوہ کفر سے پاک ہوا(ایمان کا زیور اپنایا).\nوَأَهدِيَكَمیں آپ کی رہنمائی کروں.\nنَكَالَعقوبت.\nرَفَعَ سَمكَهَااس کی چھت کو بلند کیا.\nوَأَغطَشَ لَيلَهَاغروب شمس سے اس کی رات کو اندھیر کیا.\nوَأَخرَجَ ضُحَاهَاطلوع شمس سے دن کو نمایاں اور روشن کیا.\nدَحَاهَااسے بچھایا؛ اس میں اس کی منفعت ودیعت کردی.\nالطَّامَّةُقیامت / دوسری بار کا نفخ صور.\nوَبُرِّزَتِاس کو کھول کر نمایاں کیا.\nأَيَّانَ مُرسَاهَااس کے آنے کا وقت کب ہے؟\nعَشِيَّةًظہر سے غروب شمس تک کا وقت."],[585,"§عبس\ndeeds\nآج کسی معذور یا مسکین کو خوشی دینے کی نیت سے اس سے ملاقات کیجیے.\nدعاؤں کی قبولیت کے اوقات میں سے کسی وقت کا تعین کرکے اس میں اپنے گھروالو ں کے لئے ہدایت اور مغفرت کی دعاکیجئے.\nآپ کئی اقسام کی غذائیں کھاتے ہیں، ان میں سے کسی پر خصوصیت سے غور کیجئے کہ اللہ تعالیٰ نے کس طرح اسے عدم سے وجود بخش کر آپ تک پہنچایا۔ پھر اللہ تعالیٰ کا شکر ادا کیجئے.\nguid\nاللہ تعالیٰ نے درج ذیل آیات میں اپنے نبی صلی اللہ علیہ وسلم کی سرزنش کی اور یہ آیات ہمیشہ پڑھی جاتی رہیں گی۔اس میں اس بات کی واضح دلیل ہے کہ نبی صلی اللہ علیہ وسلم سچے ہیں اور قرآن کریم اللہ کی جانب سے ہے.\nمختلف اقسام کی نعمتوں پر اللہ کا شکر کرنا چاہئے.\nقیامت کے دن کی تیاری ضروری ہے.\nrefl\nعَبَسَ وَتَوَلَّىٰٓ ١ أَن جَآءَهُ ٱلۡأَعۡمَىٰ ٢ وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ ٣ أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ ٤ أَمَّا مَنِ ٱسۡتَغۡنَىٰ ٥ فَأَنتَ لَهُۥ تَصَدَّىٰ ٦ وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ ٧ وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ ٨ وَهُوَ يَخۡشَىٰ ٩ فَأَنتَ عَنۡهُ تَلَهَّىٰ ١٠\nیہ بڑا فائدہ ہے جو رسولوں کی بعثت کا مقصد،واعظ کے وعظ اور ناصح کی نصیحت کا مقصود ہے؛ چنانچہ جو ضرورت مند خود سے آپ کے پاس آئے آپ کا اس کی جانب متوجہ ہونامناسب اور واجب ہے۔اس کے برعکس جو شخص مالداری کے زعم میں مبتلا ہو اور آپ کی بات سے بے پروائی برتے،خیر کی چاہت نہ رکھتا ہو اسی وجہ سے آپ سے پوچھے نہ آپ کی باتوں پر دھیان دے، تو اس کی جانب توجہ دینا اوراس کا خیال کرنا بالکل مناسب نہیں ہے کیونکہ اگر وہ نیکی کاراستہ نہ اپنائے تو آپ پر کوئی حرج نہیں اور اس کے گناہوں کی پوچھ گچھ بھی آپ سے نہیں ہوگی۔ یہ بات ایک قاعدہ بتاتی ہے: معلوم چیز کو موہوم چیز کی خاطر نہیں چھوڑا جاسکتا اور یقینی مصلحت کو موہوم مصلحت کی خاطر نہیں چھوڑا جاسکتا۔ (السعدی:۹۱۱)\nان آیتوں میں داعی کے لئے رہنمائی ہے کہ اسے دعوت الی اللہ میں اولویات اور ترجیحات کی رعایت کرنی چاہئے۔یہ بات واضح کیجئے.\nوَأَمَّا مَن جَآءَكَ يَسۡعَىٰ ٨ وَهُوَ يَخۡشَىٰ ٩ فَأَنتَ عَنۡهُ تَلَهَّىٰ ١٠\nداعی اسلام لانے والے سے بے رغبتی برتے اورمنہ موڑلے تو یہ ممنوع ہے۔البتہ کسی دوسرے کے اسلام قبول کرنے کی چاہت میں اس کی جانب توجہ دینایا اسے اہمیت دینا ممنوع نہیں ہے۔(الألوسی: ۱۵؍۲۴۳)\nعبداللہ ابن ام مکتوم ہدایت کی طلب میں نبی صلی اللہ علیہ وسلم کے پاس آئے تھے۔اس واقعہ میں اللہ نے کس ممنوع چیز کی طرف رہنمائی کی ہے؟\nكَلَّآ إِنَّهَا تَذۡكِرَةٞ ١١ فَمَن شَآءَ ذَكَرَهُۥ ١٢ فِي صُحُفٖ مُّكَرَّمَةٖ ١٣ مَّرۡفُوعَةٖ مُّطَهَّرَةِۢ ١٤ بِأَيۡدِي سَفَرَةٖ ١٥ كِرَامِۢ بَرَرَةٖ ١٦\n(كلَّا إنہا تذکرة)سے مراد قرآن ہے اور (بأیدی سفرة * کرام بررة) سے مراد فرشتے ہیں کہ وہ خلقت کے اعتبار سے کریم اور ہر لحاظ سے بہترین ہیں اور ان کے اعمال واخلاق بھی بہت پاکیزہ،نیک اور بلند ہیں۔اس سے یہ فائدہ حاصل ہوا کہ حافظ قرآن کے لئے یہی لائق ہے کہ وہ اپنے اقوال واعمال میں ہدایت اور خیر پر ہو۔ (ابن کثیر: ۴؍۴۷۲)\nاللہ تعالیٰ نے قرآن کے صحیفوں پر مقرر فرشتوں کی کچھ اہم صفات ذکر کی ہیں۔ان سے حافظ قرآن اور عالم کو کیا فائدہ حاصل کرنا چاہئے؟\nمِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ ١٨ مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ ١٩\nاللہ نے کافر کو کس چیز سے پیدا کیا کہ وہ تکبر کرتا ہے؟!اسے اپنی پیدائش پر گھمنڈ ہے جبکہ اسے ذلیل وحقیر جمے ہوئے پانی سے پیدا کیا گیا ہے تو آخر وہ اپنے بارے میں غلط فہمی کا شکار کیسے ہوسکتا ہے! حسن بصری رحمہ اللہ کہتے ہیں: جو دو مرتبہ پیشاب کے راستے سے نکلا ہو اسے تکبر کرنا کیسے زیب دے سکتاہے؟! (القرطبی: ۲۲؍۷۹)\nانسان کو تکبر کرنے کا حق کیوں نہیں ہے؟\nثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ ٢١\nاللہ نے اسے دفن کروا کے عزت دی، اسے دوسرے حیوانات کی طرح نہیں چھوڑدیا جن کی لاشیں زمین پر پڑی سڑتی رہتی ہیں۔ (السعدی؍۹۱۱)\nدفن ہونا نعمت کس طور پر ہے کہ اللہ نے اپنے بندوں پر اس کا احسان جتا یا ہے؟\nمِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ ١٨ مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ ١٩ ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ ٢٠ ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ ٢١\nاس سے سمجھ میں آتا ہے کہ انسان کی ابتداحقیر نطفہ کی شکل میں اور انتہابدبودار لاش کی شکل میں ہے اور وہ ان دونوں کے بیچ میں بھی پیٹ میں گندگی اٹھائے پھرتا ہے تو یقینا اسی ذات نے اسے علم سے مشرف کیا جس نے اسے بہترین شکل وصورت میں وجود بخشا اور یہ تو اس بات کا متقاضی ہے کہ انسان اس کا شکر کرے نہ کہ کفر۔ (البقاعی:۲۱؍۲۶۲)\nانسان کس سبب سے سربلند ہوتاہے اور اس کی قدر بڑھتی ہے؟\nفَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ ٢٤\nانسان کو اپنی غذا سے عبرت حاصل کرنے کا حکم دیا گیا ہے کہ کس طرح اللہ نے اپنی قدرت سے اسے پیدا کیا اور اپنی رحمت سے اسے میسر کیا چنانچہ بندے پر اپنے رب کی اطاعت اور اس کاشکر واجب ہے اور اس کی نافرمانی اور کفر ناپسندیدہ ہے۔ (ابن جُزی: ۲؍۵۳۸)\nاللہ کی مخلوقات میں غوروفکر کرنے سے انسان کو کیا نصیحت ملتی ہے؟\nwords\nسَفَرَةٍلکھنے والے فرشتے؛ جواللہ اور مخلوق کے مابین سفیر ہیں.\nنُطفَةٍمنی.\nفَقَدَّرَهُاسے مناسب تخلیق کیا.\nأَنشَرَهُاسے زندہ کیا.\nوَقَضبًاچوپائے کا چارہ.\nغُلبًابڑے درخت.\nوَأَبًّاچوپائے کے لیے گھاس."],[586,"§التكوير ، عبس\ndeeds\nاپنے چھوٹوں پر شفقت کیجئے.\nآج وہ نیک عمل کیجئے جسے آپ قیامت کے دن اپنے نامۂاعمال میں پانے کی خواہش رکھتے ہوں.\nاللہ تعالیٰ سے دین پر ثبات قدمی کی دعا کیجئے.\nguid\nحساب کے دن کو یاد رکھئے اور اس کی تیاری میں جٹ جائیے.\nاللہ تعالیٰ نے فرشتوں کو جو عزت دی ہے وہ اس بات کی متقاضی ہے کہ بندے ان پر ایمان رکھیں اور ان سے محبت کریں.\nجب نبی صلی اللہ علیہ وسلم غیب نہیں جانتے تو دوسرے بدرجۂ اولیٰ نہیں جان سکتے.\nrefl\nوَوُجُوهٞ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٞ ٤٠ تَرۡهَقُهَا قَتَرَةٌ ٤١ أُوْلَٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ ٤٢\nجو لوگ دائرۂشریعت سے اس طرح نکل گئے کہ بڑھ کر کفر کے پیشوا بن گئے۔عموماً یہ وہی عیش وعشرت کے دلدادہ مالدار لوگ ہوتے ہیں جن کا مال انہیں متکبر، گھمنڈی اور سرکش بنادیتا ہے توچونکہ ان میں کفرکے ساتھ سرکشی کی برائی بھی جمع ہوگئی تھی اسی لئے انہیں گردوغبار کے ساتھ روسیاہی کی بھی سزا دی گئی۔ (البقاعی: ۲۱؍۲۷۳)\nسرکش کافروں کو گردوغبار کے ساتھ روسیاہی کی سزا بھی کیوں دی گئی؟\nإِذَا ٱلشَّمۡسُ كُوِّرَتۡ ١ وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ ٢ وَإِذَا ٱلۡجِبَالُ سُيِّرَتۡ ٣ وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ ٤ وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ ٥ وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ ٦ وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ ٧ وَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ ٨ بِأَيِّ ذَنۢبٖ قُتِلَتۡ ٩ وَإِذَا ٱلصُّحُفُ نُشِرَتۡ ١٠ وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ ١١ وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ ١٢ وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ ١٣ عَلِمَتۡ نَفۡسٞ مَّآ أَحۡضَرَتۡ ١٤\nاللہ تعالیٰ نے ان آیات میں قیامت کی جو ہولناکیاں بیان کی ہیں ان سے دلوں پر سکتہ طاری ہوجاتا ہے،گھبراہٹ شدید ہوجاتی، رونگٹے کھڑے ہوجاتے ہیں اور چہار سوخطرہ پھیلا نظر آتا ہے۔قیامت کی یہ صفات عقلمندوں کو اس دن کے لئے تیاری کرنے پر ابھارتی ہیں اور ہر اس عمل سے روکتی ہیں جو باعث ملامت بن سکتا ہو۔ (السعدی:۹۱۲)\nقیامت کی ہولناکی بیان کرنے والی ان آیات کو پڑھنے سے ہمیں کون سا عملی فائدہ ہوتا ہے؟\nوَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ ٧\nہر شخص کو اس کے جیسا عمل کرنے والے سے ملایا جائیگاچنانچہ اللہ کی خاطر آپس میں محبت کرنے والوں کو جنت میں ملایا جائیگااور شیطان کی اطاعت میں ایک دوسرے سے محبت رکھنے والوں کو جہنم میں ملادیا جائیگا۔اس طرح ہر آدمی چاہے یا نہ چاہے اسی کے ساتھ رہیگا جس سے دنیا میں محبت رکھتا ہوگا۔(ابن القیم: ۳؍۲۵۷)\nآپ کا دنیا میں کسی سے محبت کرنا آخرت پر اثر انداز ہوگا۔اس کی وضاحت کیجئے.\nوَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ ٨ بِأَيِّ ذَنۢبٖ قُتِلَتۡ ٩\nاس سے یہ بتانا مقصود ہے کہ اس معصوم جان کا کوئی گناہ نہیں تھا کہ وہ اس گناہ میں قتل کی جاتی بلکہ جرم تو اس کے قاتل کا ہے لیکن اس جرم کی شدت بتانے اور قاتل کو مزید ذلیل کرنے کے لئے اس بے گناہ سے سوال کیا جائیگا۔(الشنقیطی: ۸؍۴۳۸)\nزندہ دفن کی گئی لڑکی بے گناہ ہے تو پھر اس سے سوال کیوں کیا جائیگا؟\nإِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ ١٩ ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينٖ ٢٠ مُّطَاعٖ ثَمَّ أَمِينٖ ٢١\nیہ سب باتیں اللہ کے نزدیک قرآن کے مقام و مرتبہ پر دلالت کرتی ہیں کہ بہترین صفات سے متصف معزز فرشتہ کے ذریعہ اسے بھیجاگیا اور دستور یہی ہے کہ بادشاہ عمدہ مقاصد کے لئے بہترین پیغام کے ساتھ اپنے یہاں کے سب سے معزز فرد کوہی بھیجتے ہیں۔(السعدی؍۹۱۳)\nقرآن کی وحی لے کر آنے والے فرشتہ کی مذکورہ صفات کو نظر میں رکھتے ہوئے اللہ کے نزدیک قرآن کے مرتبہ کو واضح کیجئے.\nوَمَا هُوَ بِقَوۡلِ شَيۡطَٰنٖ رَّجِيمٖ ٢٥ فَأَيۡنَ تَذۡهَبُونَ ٢٦ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ٢٧\nجو قرآن کریم کے ان اوصاف کو جان لے اور فرشتوں میں سے اسے لانے والے اور انسانوں میں سے جن پر نازل ہوا ان دونوں کے اوصاف سے بھی آگاہ ہوجائے تو وہ یقینا قرآ ن سے محبت کریگا اور ان دونوں سے بھی،وہ ان کی بدرجۂ اتم تعظیم وتوقیر کریگا۔ہر وقت قرآن کریم کی تلاوت کرنے کی کوشش کریگا،اس کے ہر حکم کو لازماً بجالائیگا اور اس کے منع کئے ہوئے کاموں سے رکے گا تاکہ اسے استقامت حاصل ہوسکے اور ان سب کے پیچھے اس کا مقصد جس پر نازل کیا گیا اس(نبی صلی اللہ علیہ وسلم) کا ساتھ پانا اور جس نے نازل کیا (اللہ تعالیٰ) اس کے دیدار سے مشرف ہونا ہوگا۔(البقاعی: ۲۱؍۲۹۴)\nہم اگر قرآن کریم کے اوصاف اور نبی صلی اللہ علیہ وسلم کے اوصاف جانیں تو اس سے ہمیں کیا فائدہ ہوگا؟\nإِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ٢٧ لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ ٢٨\nقرآن کریم تمام لوگوں کے لئے نصیحت ہے کہ سب اس سے نصیحت حاصل کریں اور عبرت پکڑیں :(إن ہو إلا ذکر للعالمین * لمن شاء منکم أن یستقیم) یعنی جو ہدایت کا خواہش مند ہو وہ اس قرآن کی اتباع کرے بیشک یہی اس کے لئے سبب ِ نجات وہدایت ہے،کوئی دوسری چیز نہیں۔ (ابن کثیر: ۴؍۴۸۱)\nآج انسان گمراہی اورجہالت سے نجات حاصل کرنے کے لئے سیدھے راستہ کی تلاش میں حیران ہے۔ آپ کے خیال میں نجات اور ہدایت کا واحد ذریعہ کیا ہے؟\nwords\nقَتَرَةٌذلت / اندھیر/ ظلمت.\nانكَدَرَتوہ بکھر گیا؛ اس کا نور ختم ہو گیا.\nالعِشَارُحامل اونٹنیاں.\nعُطِّلَتجسے چھوڑ دیا گیا ہو.\nسُجِّرَتوہ بھر گئی حتی کہ بہہ پڑی۔ پھوٹ پڑی.\nالمَوءُودَةُزندہ درگور بچی.\nكُشِطَتختم کردی گئی؛ اکھیڑ دی گئی.\nأُزلِفَتوہ قریب کردی گئی."],[587,"§الانفطار ، المطففين\ndeeds\nقبرستان کی زیارت کیا کیجئے.\nاللہ نے آپ کو بہترین سانچے میں بنایا ہے اس پر اللہ کا شکر ادا کیجئے.\nاپنے کسی گناہ کویاد کرکے اس پر اللہ سے معافی مانگئے.\nguid\nآدمی نیک کاموں میں جلدی کرے۔اللہ کے کرم اور معافی پر بھروسہ کرکے غافل نہ ہوجائے.\nانسان کا بہترین سانچے میں پیداہونا اس پر اللہ کی عظیم نعمتو ں میں سے ہے.\nہر کام جو آپ کرتے ہیں وہ آپ کے حق میں یا آپ کے خلاف لکھا جاتا ہے.\nrefl\nيَٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ ٦\nاحسان کی بات کرنے کے ساتھ ’’رب‘‘کی تعبیر لانا دراصل یہ بتانا ہے کہ اگر کوئی مسلسل سرکشی پر اترا ہو تو اس کا مربی اسے سزا ضرور چکھاتا ہے کیونکہ یہ مربی کے فرائض میں داخل ہے۔اب جو اس پر غور کریگا تو یہ بات اسے برائی سے روکنے میں مددگار ہوگی۔ (البقاعی: ۲۱؍۳۰۲)\nآیت میں رب کی تعبیر کس بات پر لالت کرتی ہے؟\nوَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ ١٠ كِرَامٗا كَٰتِبِينَ ١١ يَعۡلَمُونَ مَا تَفۡعَلُونَ ١٢\nاللہ تعالیٰ نے انسانوں کے ساتھ معزز فرشتے لگا رکھے ہیں جو ہمارے اقوال واعمال لکھتے ہیں اور ہمارے سب کاموں سے واقف بھی رہتے ہیں چنانچہ ہمارے لئے یہی مناسب ہے کہ ان کی عزت واحترام کریں اور ان کے وقا ر کا خیال رکھیں۔ (السعدی؍۹۱۴)\nاعمال لکھنے والے فرشتوں کے بارے میں آپ کا کیا احساس ہے؟اور یہ احساس آپ سے کیا تقاضہ کرتا ہے؟\nإِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ ١٣\nان لوگوں کا بدلہ دنیا میں ہے،برزخ میں اور جنت میں دلی،روحانی اور جسمانی نعمتیں ہیں۔(السعدی؍۹۱۴)\nاللہ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت انسان کے لئے تینوں مرحلوں میں نعمت او ر سعادت کا سبب بنتی ہے۔بتائیے وہ تین مرحلے کون سے ہیں جن سے انسان گزرتا ہے؟\nإِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ ١٣ وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ ١٤\nیہ نہ سمجھیں کہ آیت میں صرف جنت کی نعمت اور جہنم کے عذاب کا تذکرہ ہے بلکہ تینوں ہی گھروں میں دنیا،برزخ اور آخرت میں نیک لوگ نعمتوں میں ہی رہتے ہیں اور فاجر جہنم میں رہتے ہیں کیونکہ اصل نعمت تو دل کا قرار اور اطمینان ہی ہے اور عذاب دل کا عذاب ہے۔بھلابتائیےڈر،بے چینی،غم،سینہ کی تنگی، اللہ اور آخرت سے بے پروائی،اور دل کا اللہ سے کٹ کر مخلوق سے تعلق جوڑلینااور دنیا کی ہی الگ الگ وادیوں میں حیران بھٹکنا اس سے بڑا عذاب اور کیا ہوسکتا ہے!اب جوبھی اللہ کے علاوہ سے تعلق جوڑے اور اسی سے محبت کرے تو یقینا اسے رسوا کن تکلیف دہ عذاب پہنچ کر رہے گا۔ (ابن القیم: ۳؍۲۶۷)\nآیت میں ذکر کردہ نعمت او ر عذاب کا تعلق کس جگہ سے ہے؟\nوَيۡلٞ لِّلۡمُطَفِّفِينَ ١\nاس جملہ سے سورت کی شروعات کرنا دراصل اس کام کی خطرناکی کو بتانا ہے اور یقینایہ کام بہت ہی خطرناک ہے اس لئے کہ ناپ تول کے درست ہونے پر ہی پوری دنیا کی معیشت اور اقتصادیات ٹکی ہوئی ہے اور اسی کے مطابق لوگ ایک دوسرے کے ساتھ معاملہ کرتے ہیں تو اگر اسی میں کوتاہی ہو تو لازماً دنیا کی معاشیات پر اس کا منفی اثر پڑتا ہے اور اس کے نتیجہ میں لوگوں کے معاملات خراب ہوتے ہیں اور یہ بڑا فساد ہے۔ (الشنقیطی: ۸؍۴۵۴)\n’’ناپ تول میں کمی کرنے والوں کے لئے ہلاکت ہے‘‘۔اس جملہ سے سورت شروع کرنے کا کیا فائدہ ہے؟\nوَيۡلٞ لِّلۡمُطَفِّفِينَ ١ ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ ٢ وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ ٣\nاس میں اس بابت تنبیہ ہے کہ اصل آفت تو برے اخلاق ہیں جن میں سے دنیا کی بےجا محبت بھی ہے جو انسان کو ہر جائز وناجائز ذریعہ سے مال جمع کرنے پر مجبور کرتی ہے،پھر وہ ناجائز ذریعہ ڈنڈی مارنے جیسا ہی خراب کیوں نہ ہو اور ڈنڈی مارنا تو ایسا کام ہے جسے کوئی بھی اچھی فطرت والا آدمی گوارا نہیں کرتا۔ اچھی فطرت والے تو وہ ہیں جو بھرپور ناپتے اور وزن پورا کرتے ہیں،نہ کم دیتے ہیں اور نہ ڈنڈی مارتے ہیں۔(البقاعی: ۲۱؍۳۱۱)\nاصل آفت کیا ہے اور ڈنڈی مارنے سے اس کا کیا تعلق ہے؟\nأَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ ٤ لِيَوۡمٍ عَظِيمٖ ٥ يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ ٦\nاس انکار اور تعجب میں،ظن وگمان کا لفظ استعمال کرنے،قیامت کے دن کو عظیم کہنے،اس دن سب کا نظریں جھکائے اللہ کے سامنے کھڑا ہونے کا ذکر کرنے اور اللہ کی صفت رب العالمین لانے میں اس بات کا مضبوط بیان ہے کہ ڈنڈی مارنا بڑاجرم ہے اور اس کا گناہ بہت ہے۔ (القرطبی: ۲۲؍۱۳۶۱)\nاللہ تعالیٰ نے ڈنڈی مارنے کا گناہ کس حد تک بڑا بتایا ہے؟\nwords\nانفَطَرَتوہ پھٹ پڑے.\nانتَثَرَتوہ گر جائے.\nفُجِّرَتوہ بھر جائے؛ اور بہہ پڑے.\nبُعثِرَتجائے دفن سے اٹھایا گیا.\nمَا غَرَّكَ بِرَبِّكَکس نے دھوکہ میں رکھا؛ اپنے رب کے کفر پر جری کیا.\nفَسَوَّاكَآپ کو درست بنایا؛ معتدل اور پورے اعضاء والا.\nفَعَدَلَكَآپ کو تخلیق میں معتدل بنایا.\nلَحَافِظِينَنگہبان فرشتے جو آپ کے اعمال لکھتے ہیں.\nبِغَائِبِينَوہ جہنم سے نہ نکالے جائیں گے۔ اور نہ وہ مریں گے.\nلِلمُطَفِّفِينَجو لوگ ماپ تول میں کمی کرتے ہیں."],[588,"§المطففين\ndeeds\nیہ دعا مانگئے:’’اَللّٰہُمَّ اِنّی اَسْئَلُكَ لَذَّۃ َ النَّظَرِ اِلیٰ وَجْہِكَ الْكَرِیْم فیْ غَیْرِ ضَرَّاءَ مُضِرَّۃٍ وَلَا فِتْنَۃٍ مُضِلَّۃٍ‘‘اے اللہ! میں تجھ سے دعا کرتا ہوں کہ تو مجھے اپنے کریم چہرے کو دیکھنے کی سعادت عطافرما، کسی نقصان یا گمراہ کن فتنے کے خوف سے نہیں (بلکہ تیری محبت کے شوق سے).\nکسی مسلمان کو پانی کا صدقہ دیجئے.\nاس شخص کو دیکھئے جو ہر نماز کے لئے جلدی مسجد جاتا ہو اور اس سے اس خیر میں مقابلہ کیجئے.\nguid\nاللہ تعالیٰ آخرت میں کسی کو اپنے دیدار سے محروم کردے یقینایہ بھی بڑی سزا ہوگی.\nگناہ دل پر زنگ لگ جانے کا سبب ہیں.\nنیک کاموں میں ایک دوسرے سے مقابلہ آرائی کرنا مومنوں کی صفات میں سے ہے.\nrefl\nكَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ ١٤\nاس سے مراد گناہ پر گناہ کرنا ہے حتی کہ دل کالا ہوجائے۔ مجاہد رحمہ اللہ کہتے ہیں: مراد وہ شخص ہے جو گناہ کرتا ہے تو گناہ اس کے دل کو گھیرلیتا ہے،پھر گناہ کرتا ہے تو گھیرا اور بڑھ جاتا ہے حتی کہ گنا ہ اس کے دل پرچھاجاتے ہیں۔بکر بن عبداللہ رحمہ اللہ کہتے ہیں: بندہ جب کوئی گناہ کرتا ہے تو اس کے دل پر سوئی کے نوک کی مانند سوراخ ہو جاتا ہے،پھر گناہ کرتا ہے تو دوبارہ ایسا ہی سوراخ ہوجاتاہے حتی کہ گناہوں کی کثرت سے اس کا دل چھلنی کے جیسا ہوجاتا ہے تب نہ تو وہ کسی خیر کو سمجھ پاتا ہے اور نہ ہی اس میں کوئی اچھائی ٹکتی ہے۔(القرطبی: ۲۲؍۱۴۳)\nآیت میں زنگ سے کیا مراد ہے او ر وہ بندے کے دل تک کیسے پہونچتا ہے؟\nكَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ ١٤\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: بندہ جب کوئی گناہ کرتا ہے تو اس کے دل پر ایک کالا دھبہ پڑجاتا ہے پھر اگر توبہ کرلے تو اس کا دل صاف ہوجاتا ہے لیکن اگر دوبارہ کرے تو پھر سے داغ لگ جاتا ہے اور گناہوں کی کثرت سے وہ داغ بڑھتے بڑھتے پورے دل کو ڈھانپ لیتا ہے اور یہی وہ ﴿أَرِنَا﴾ ہے جسے اللہ تعالیٰ نے بیان کیا ہے :(کلا بل ران علی قلوبہم ما کانوا یکسبون) (الطبری: ۲۴؍۲۸۶)\nدل پرلگے ہوئے زنگ کو دور کرنے میں توبہ کا کیا اثر ہوتا ہے؟واضح کیجئے.\nكَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ ١٥\nحسین بن فضل رحمہ اللہ کہتے ہیں: اللہ تعالیٰ نے جس طرح انہیں دنیا میں اپنی توحید سے محروم کردیا تھا اسی طرح آخرت میں انہیں اپنے دیدار سے محروم کردے گا۔زَجّاج رحمہ اللہ کہتے ہیں: اس آیت میں دلیل ہے کہ قیامت کے دن اللہ تعالیٰ کو دیکھا جاسکے گا۔(الشوکانی: ۵؍۴۰۰)\nآخرت میں فاجرو ں کو اللہ کے دیدار سے کیوں محروم کردیا جائیگا؟\nخِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ ٢٦\n(المتنافسون) یعنی اللہ کی اطاعت میں تیزی دکھانے والے۔﴿تَنَفَّسَ﴾کا اصل معنی ہے عمدہ چیز کے حصول کے لئے دوسروں کو پچھاڑنا اور بلند مرتبہ لوگوں کی مشابہت اختیار کرنے اور ان تک پہنچنے کے لئے خوب جدوجہد کرنا مگر اس طرح کہ دوسروں کو نقصان نہ پہنچے۔ اس طور پر اس میں شرافت نفس اور بلندہمتی کا معنی بھی پایا جاتا ہے۔ (الألوسی: ۱۵؍۲۸۳)\nاس آیت میں مذکور قابل تعریف مقابلہ آرائی سے کیا مراد ہے؟\nخِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ ٢٦\nاس آیت میں سورت کے ابتدائی حصہ کی طرف اشارہ ہے وہ اس طرح کہ جب وہ لوگ کانٹے مار کر دوسروں کے حق چھین کر مال جمع کرنے میں لگے ہوئے ہیں تو قیامت کے دن ان کے لئے تباہی ہے اور جبکہ نیک لوگ قیامت کے دن نعمتوں میں ہوں گے اور یہ ان کا مشروب ہے تو اصل مقابلہ آرائی کا مقام یہ ہے نہ کہ محبت میں یا فانی چیزوں کی آس میں کسی کا حق مارنا۔ (الشنقیطی: ۸؍۴۶۳)\nسورت میں کس مقابلہ آرائی کو اچھا اور کسے برا بتایا گیا ہے؟\nوَمِزَاجُهُۥ مِن تَسۡنِيمٍ ٢٧ عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ ٢٨\nتسنیم جنت کا اعلیٰ ترین مشروب ہے۔اللہ تعالیٰ نے بتایا ہے کہ عام نیک لوگوں کے مشروب میں تسنیم کی آمیزش ہوگی جبکہ مقرب بندے خالص تسنیم پئیں گے۔یہ فرق اس وجہ سے کہ بدلہ عمل کے موافق ہی ہوتا ہے تو چونکہ مقرب بندوں کے اعمال اللہ کے لئے خالص تھے اس لئے ان کا مشروب بھی خالص ہوگااور عام نیک لوگوں نے نیکیوں کی ساتھ دوسرے مباح کام بھی کئے ہوں گے اس لئے ان کا مشروب بھی ملاجلا مخلوط ہوگا۔چنانچہ جو خالص ہوگا اس کا مشروب خالص ہوگا اور جس کا عمل مخلوط ہوگا اس کا مشروب بھی مخلوط ہوگا۔(ابن القیم: ۳؍۲۷۰)\nمقرب بندوں کا مشروب خالص تسنیم کا جبکہ عام نیک بندوں کے مشروب میں تسنیم کے ساتھ کچھ اور کیوں ملا ہوگا؟\nوَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ ٣١\nکفار مومنوں کو دکھ پہنچاکربہت خوش اور اتراتے ہوئے گھروں کو جاتے تھے۔یہ دھوکا کھانے کا اونچا درجہ ہے وہ اس طرح کہ وہ خوب برائیاں کرنے کے باوجود دنیا میں امن وچین سے رہے۔ایسا لگتا تھا کہ ان کے پاس اللہ کا مکتوب یا عہد آیا ہو کہ وہ اہل ِسعادت میں سے ہیں،اس کے علاوہ انہوں نے اپنے ہدایت پر ہونے اور مومنوں کے گمراہ ہونے کا حکم لگالیا تھا۔یہ محض اللہ پر جھوٹ باندھنا اور بلا علم اس کی طرف غلط بات منسوب کرنے کی جسارت تھی۔ (السعدی؍۹۱۶)\nبیان کیجئے وہ بڑی برائی کیا ہے جسے اللہ تعالیٰ نے ان مشرکوں کے حال کے ضمن میں بیان کیا ہے؟\nwords\nسِجِّينٍجیل / قید / تنگی.\nمَرقُومٌکپڑے پر لکھا ہوا جو مٹ نہ سکے.\nأَسَاطِيرُباطل کہانیاں.\nرَانَاس کو ڈھانک لیا.\nالأَرَائِكِمزین تخت پوش.\nرَحِيقٍصاف شراب.\nوَمِزَاجُهُاور اس میں ملاوٹ.\nتَسنِيمٍاعلی ترین جنت میں ایک چشمہ.\nيَشرَبُ بِهَاوہ اس سے لذت حاصل کرنے کے لیے پیتے ہیں."],[589,"§الانشقاق\ndeeds\nغوروفکر کرتے ہوئے قرآن کریم کی تلاوت سنئے.\nسورتو ں میں آئی ہوئی آیات سجدہ پر سجدۂ تلاوت کیجئے.\nآج سے ہر اچھا کام دائیں جانب سے کرنے کی کوشش کیجئے.\nguid\nان آیتوں میں قیامت کی بعض ہولناکیوں کا ذکر ہے.\nجس طرح یہ بڑی بڑی مخلوقات اللہ کی فرمانبردار ہیں آپ بھی بنئے.\nجھٹلانے والوں کے لئے بڑی دھمکی ہے.\nrefl\nعَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ ٣٥\nجنتیوں کو جنت میں صرف یہی کام ہوگا کہ وہ جنت کی انواع واقسام کی نعمتوں،نہروں،حوروں اور خوبصورت خادموں یا ان کے علاوہ لذتوں میں مصروف رہیں گے اور انہی کو دیکھیں گے۔امام قُشیری رحمہ اللہ کہتے ہیں: اللہ نے یہاں بس یہ کہا ہے کہ’’وہ دیکھ رہے ہوں گے‘‘ مگر کیا دیکھ رہے ہوں گے؟اس کی وضاحت نہیں کی ہے۔اس کی وجہ یہ ہے کہ سارے لوگ الگ الگ چیزوں کو دیکھ رہے ہوں گے مثلاً کوئی اپنے محلوں کو دیکھ رہاہوگا،کوئی حوروں کو اور کوئی دوسری نعمتوں کو۔ بہت ہی خاص لوگ تو ہمیشہ اللہ تعالیٰ کو دیکھیں گے اس کے برخلاف کافر ہمیشہ ہی اپنے رب کی دید سے محروم رہیں گے۔ (البقاعی: ۲۱؍۳۲۷)\nاللہ تعالیٰ نے یہ تو بتایا ہے کہ مومنین جنت میں دیکھیں گے مگر یہ نہیں بتایا کیادیکھیں گے؟اس کی کیا وجہ ہے؟\nيَٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحٗا فَمُلَٰقِيهِ ٦\nاس میں اچھے ڈھنگ سے عمل کی کوشش کرنے پر ابھارا گیا ہے اس لئے کہ جو یہ یقین رکھے گا کہ اسے لازمی طور سے اللہ تعالیٰ کے سامنے پیش ہونا ہے،وہ پوری لگن اور جذبہ سے ان کاموں کے لئے اپنی کوشش وقف کردیگا جن پر اللہ ملاقات کے وقت اس کی تعریف کرے۔ (البقاعی: ۲۱؍۳۳۹)\nبندہ جان لے کہ یقینا وہ اپنے رب سے ملنے والا ہے تو اس پر کیا واجب ہوجاتا ہے؟\nوَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورٗا ٩\nدنیا میں مومن اپنے گھر والوں کے ساتھ رہتے ہوئے بھی اللہ کے سامنے پیش ہونے سے ڈرتا رہتا تھا،اسے ہمیشہ یہی فکر دامن گیر رہتی،اسی کی خاطر وہ بےچین رہتا اور اسی وجہ سے صبح وشام اپنا سخت محاسبہ کیا کرتا تھا حالانکہ وہ گھر والوں کا خیال رکھنے کے لئے مشقت اٹھاتا، زندگی کی سختی بھی جھیلتاتھا اور اس کے علاوہ مخالفین کی جانب سے پہنچائی جانے والی تکالیف بھی برداشت کرتا تھا۔ (البقاعی: ۲۱؍۳۴۱)\nمومن کو جنت میں اہل ِخانہ کے ساتھ خوش رہنے کا انعام کیوں دیا جائیگا؟\nوَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ ١٠\nکافروں کو پیٹھ کے پیچھے سے نامۂ اعمال دیے جانے کی وجہ یہ ہوسکتی ہے کہ نامۂ اعمال تقسیم کرنے والے فرشتے ان کافروں کی ڈروانی شکلیں دیکھنے کی تاب نہیں لاسکیں گے یایہ کہ شدت ِنفرت کی وجہ سے ان کا سامنا نہیں کریں گے۔یایہ بھی وجہ ہوسکتی ہے کہ جیسے ان کافروں نے اللہ کی کتاب اور اس کے احکام کو پیٹھ کے پیچھے ڈال دیا تھا تو انہیں بھی پیٹھ کے پیچھے سے نامۂ اعمال دیے جائیں گے۔ (الألوسی: ۳۰؍۸۱)\nکافر کو نامہ اعمال پیٹھ کے پیچھے سے کیوں دیا جائیگا؟\nإِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا ١٣\nکافر اپنے گھروالوں کے ساتھ مستی میں رہتا تھا نہ اسے انجام کی فکر تھی اور نہ مستقبل میں پیش آنے والے کسی عذاب کا ڈر تھا تو اس ختم ہونے والی مستی نے اسے کبھی نہ ختم ہونے والے دکھوں کا وارث بنادیا۔ (ابن کثیر: ۴؍۴۹۰)\nخوشی کب قابل مذمت بن جاتی ہے؟\nإِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ ١٤\nاس آیت سے یہی معلوم ہوتا ہے کہ دوبارہ زندہ کئے جانے کو تسلیم نہ کرنا یا اس میں شک کرنا دراصل یہی ہر برائی کا سبب اور ہر اچھائی سے محرومی کا باعث بنتا ہے اس کے برعکس یوم آخر پر ایمان رکھنا ہی ہر خیر کے حصول پر آمادہ کرنے والا اور ہر شر سے روکنے کا ذریعہ بنتا ہے۔چنانچہ قیامت کے دن پر ایمان رکھنا ہی تمام نیک اعمال کا سبب ہے اور یہی بات قرآن کریم کے شروع میں بیان کی گئی ہے: ﴿هُدٗى لِّلۡمُتَّقِينَ ...﴾ (الشنقیطی: ۸؍۴۱۷)\nقیامت پر ایمان نہ رکھنا یا اس میں شک کرنا ہر برائی کی بنیاد کیسے بنتا ہے؟\nبَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرٗا ١٥\nاللہ تعالیٰ ہر انسان کو ہر پہلو سے دیکھنے والا اور اس کی بابت مکمل علم رکھنے والا ہے تو انسان کے اعمال کا علم رکھنے کے باوجود اسے یونہی چھوڑدینا اللہ تعالیٰ کی حکمت،عدل اور بادشاہت کے منافی ہے اور یہ ایسی چیز ہے جو عقل کسی طورتسلیم نہیں کرتی۔(البقاعی:۲۱؍۳۴۵)\nاللہ تعالیٰ بندے کو دیکھتا ہے۔یہ خبر کس بات پر دلالت کرتی ہے؟\nwords\nانشَقَّتپھٹ جائیں گے۔ (بروز قیامت بادل پھٹ جائیں).\nوَأَذِنَت لِرَبِّهَااپنے رب کے حکم کی اطاعت.\nمُدَّتبچھا دیا گیا؛ اس میں وسعت دی گئی.\nيَدعُو ثُبُورًاہلاکت کی بد دعا.\nلَن يَحُورَوہ ہر گز اللہ تعاليٰ کی طرف نہیں لوٹیں کہ وہ ان سے حساب لے.\nوَسَقَجمع کیا.\nاتَّسَقَاس کا نور کامل ہوگیا؛ روشن ہوگیا.\nطَبَقًا عَن طَبَقٍمتعدد اطوار / مختلف أحوال."],[590,"§البروج ، الانشقاق\ndeeds\nکسی ایک یا ایک سے زائد مسلمان کو اللہ کی راہ میں پہونچنے والی تکلیفوں پر صبر کی نصیحت کیجئے.\nکسی پریشان حال مسلمان کی مدد کیجئے.\nکسی ایک یا ایک سے زائد مسلمان کو بتائیے کہ اللہ’’غفور ودود‘‘ (بہت بخشنے والا اور اپنے بندوں سے محبت کرنے والا)ہے.\nguid\nگذشتہ امتوں کے مسلمان کیسی کیسی قربانیا ں دے کر دین پر ثابت قدم رہے ہیں۔آپ ان کے حالات سے عبرت پکڑئیے.\nاللہ تعالیٰ دشمنوں سے اپنے محبوب بندوں کا بدلہ لیتا ہے.\nمسلمانوں کو تکلیف پہنچانے سے توبہ کرلیجئے.\nrefl\nوَشَاهِدٖ وَمَشۡهُودٖ ٣\nمخلوق میں سے بہت سے ایسے ہوتے ہیں جن کے خلاف گواہی دی جاتی ہے۔ اس کے بغیر کائنات کا نظام چل بھی نہیں سکتا تو یہ کیسے ہوسکتا ہے کہ مخلوق ایک تو دوسرے پر گواہ ہو،اس کا نگراں اوراس کی خبر رکھنے والا ہو اور اللہ تبارک وتعالیٰ جو خالق ہے وہ اپنے بندوں سے باخبر نہ ہو اور ان کا نگراں نہ ہو!(ابن القیم: ۳؍۲۷۸)\nیہ بتانے کا کیافائدہ ہے کہ مخلوق میں سے کوئی گواہ ہے اورکوئی وہ ہے جس کے حق میں یا اس کے خلاف گواہی دی جاتی ہو؟\nقُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ ٤ ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ ٥\nہمارے علماء کہتے ہیں: اللہ عزوجل نے اس آیت میں امت محمدیہ کے مومنین کو بتایا ہے کہ ان سے پہلے ایمان لانے والوں کو کتنی سخت تکلیفیں برداشت کرنی پڑیں۔اللہ اس کے ذریعہ مومنوں کو حوصلہ دلانا چاہتا ہے۔پھر نبی صلی اللہ علیہ وسلم نے بھی مومن لڑکے کا قصہ بیان کیا ہے تاکہ ہم بھی تکلیفوں،مشقتوں اور دکھوں کو برداشت کرنے میں اس لڑکے کو اپنا نمونہ بناسکیں جس نے حق کی خاطر صبر کیا،مضبوطی سے ایمان پر جمارہا اورنہایت صبر وضبط سے دعوت الی اللہ کا فریضہ انجام دیتا رہا حتی کہ اپنی جان قربان کردی۔بہت سے لوگ اس کے ہاتھ پر ایمان لائے حالانکہ وہ چھوٹا بچہ تھا۔(القرطبی: ۲۲؍۱۹۲–۱۹۳)\nاللہ تعالیٰ نے ہم سے خندق والوں کا قصہ کیوں بیان کیا ہے؟\nٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ٩\n(الذی لہ ملک السموات والأرض) آسمان اور زمین کی ہر چیز اللہ کی مخلوق اور اس کی غلام ہے،اللہ مالک ہے اور وہ اپنے مملوک کی طرح ان سب میں تصرف کرتا ہے(واللہ علی کل شیء شہید) اور اللہ اپنے علم،سننے او ر دیکھنے کے اعتبار سے ہر چیز پر گواہ ہے تو کیا اللہ کے مقابلہ میں سرکشی کرنے والے لوگ ڈرتے نہیں کہ اللہ انہیں پکڑ لے؟ یا انہیں معلوم نہیں کہ وہ سب اللہ کے غلام ہیں اور مالک کی اجازت کے بغیر کسی غلام کو دوسرے غلام پر کوئی غلبہ نہیں ہوتا؟کیا وہ اس بات سے واقف نہیں ہیں کہ اللہ ان کے تمام اعمال کا احاطہ کئے ہوئے ہے اور انہیں ان کے عمل کا بدلہ دے گا؟ بیشک کافر تو دھوکے میں پڑے ہوئے ہیں اور جاہل سیدھے راستہ سے دور جہالت اور اندھے پن میں بھٹک رہا ہے۔ (السعدی؍۹۱۸)\nاللہ تعالیٰ نے خندق والے ظالم سرکشوں کا ذکر کرنے کے بعد اپنے زمین وآسمان کامالک ہونے کا ذکر کیوں کیا ہے؟\nإِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ ١٠\nحسن بصری(رحمہ اللہ) کہتے ہیں:اللہ تعالیٰ کے کرم اور فیاضی پر غور کیجئے کہ ان ظالموں نے اللہ کے نیک بندوں کو قتل کردیا پھر بھی اللہ انہیں توبہ کرنے اور معافی مانگ لینے کی دعوت دے رہا ہے۔ (ابن کثیر: ۴؍۴۹۷)\nآیت سے اللہ تعالیٰ کا کرم اور فیاضی کیسے سمجھی جاسکتی ہے؟\nوَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ ١٤\nعلماء کہتے ہیں:’’مودّت‘‘وہ خالص محبت ہےجس میں کوئی کھو ٹ نہ ہو۔ اللہ تعالیٰ نے ﴿لَغَفُورٌ﴾ کے ساتھ﴿ٱلۡوَدُودُ﴾ صفت ذکر کی ہے اس میں یہ باریک نکتہ ہے کہ اگر گناہ گار بندے توبہ کرلیں اور اللہ سے رجوع ہوجائیں تو اللہ ان کے گناہ بخش دیگا اور ان سے محبت بھی کریگا۔ (السعدی؍۹۱۹)\nاللہ تعالیٰ کے آیت میں اپنی صفت”الغفور’’کے ساتھ‘‘الودود“ذکر کرنے میں کیا راز ہے؟\nهَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ ١٧ فِرۡعَوۡنَ وَثَمُودَ ١٨\nان آیتوں کے ذریعہ نبی صلی اللہ علیہ وسلم کو تسلی دینا مقصود ہے کہ آپ کی کافر قوم اسی سے دوچار ہوگی جس سے وہ لوگ دوچار ہوئے۔معنیٰ یہ ہے کہ: آپ کو فرعون اور ثمود کے واقعات معلوم ہوچکے ہیں،آپ جانتے ہیں کہ انہوں نے کیا کیا اور ان کے ساتھ کیا کیا گیا!اب آپ اپنی قوم کو اللہ تعالیٰ کے اس قانون اور سزا سے ڈرائیے اور انہیں خبردار کیجئے کہ کہیں ان پر بھی وہ عذاب نہ آجائے جو فرعون اور ثمود پر آیا تھا۔ (الألوسی: ۳۰؍۳۹)\nاس آیت میں کفار قریش کے لئے دھمکی ہے اور انہیں خبردار کرنا ہے۔وہ کس طرح؟وضاحت سے بتائیے.\nبَلۡ هُوَ قُرۡءَانٞ مَّجِيدٞ ٢١ فِي لَوۡحٖ مَّحۡفُوظِۢ ٢٢\n(فی لوح محفوظ): قرآن ہر طرح کی تبدیلی،زیادتی اور کمی سے محفوظ ہے، اسی کے ساتھ شیاطین سے بھی محفوظ ہے۔لوح محفوظ وہ ہے جہاں اللہ نے ہر چیز کو لکھ رکھا ہے۔ قرآن کا لوح محفوظ میں ہونا اللہ کے نزدیک قرآن کی جلالت قدر،بلند مرتبہ والا ہونے اور مستحکم ہونے کی دلیل ہے۔(السعدی؍۹۱۹)\nآیت پر غور کرتے ہوئے بتائیے کہ اللہ کے یہاں قرآن کا کیا مقام ہے؟\nwords\nغَيرُ مَمنُونٍغیر مقطوع ؛ کم نہ ہونے والا.\nذَاتِ البُرُوجِمنازل والا ؛ جس سے سورج اور چاند گزرتے ہیں.\nوَاليَومِ المَوعُودِقیامت کا دن.\nوَشَاهِدٍ وَمَشهُودٍاللہ تعاليٰ نے قسم اٹھائی ہے؛ ہر شاہد کی؛ اورجس پر شہادت دی گئی ہے؛ اس کی.\nقُتِلَہلاک ہوگیا؛ عذاب دیا گیا.\nأَصحَابُ الأُخدُودِوہ لوگ جن کو جلانے کے لیے خندقیں کھودی گئی.\nعَذَابُ الـحَرِيقِجلا دینے والا عذاب.\nالوَدُودُاپنے دوستوں سے محبت کرنے والا."],[591,"§الطارق ، الأعلى\ndeeds\nاپنے کسی گناہ کو یاد کیجئے جو کسی کو معلوم نہ ہوسکا ہو اور اللہ سے اس کی معافی مانگئے.\nکوئی سورت پڑھئے یا اسے یاد کیجئے.\nاللہ عزوجل کا تقویٰ اختیار کرنے پر ابھارنے والا کوئی پیغام بھیجئے.\nguid\nیہ یاد رکھنا کہ آپ مٹی سے پیداکئے گئے ہیں آپ کو تکبر سے بچائیگا.\nدین سے رخ موڑنے والوں کو اللہ تعالیٰ مہلت دیتا ہے یہ دراصل اس کی تدبیر ہے،آپ محتاط ہوجائیے.\nانسان کے لئے اپنے دل کے اعمال اور تنہائی کے اعمال پر متنبہ رہنا ضروری ہے کیونکہ اللہ تعالیٰ سب کچھ جانتاہے.\nrefl\nيَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ ٩\nانسان کی چھپی ہوئی باتیں نکال کر ظاہر کردی جائیں گی۔ہر وہ اچھائی یا برائی جو انسان چھپاتا ہے اور اسی طرح اس کے سینہ میں چھپا ہوا ایمان اور کفر بھی۔ عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں: قیامت کے دن اللہ تعالیٰ ہر پوشیدہ راز کو ظاہر کردیگا، اس سے بہت سے لوگوں کی عزت بڑھ جائیگی اور بہت سے لوگ ذلیل ہوجائیں گے۔(القرطبی: ۲۲؍۲۱۲–۲۱۴)\nقیامت کے دن بندے کے راز کیسے فاش ہوجائیں گے؟\nيَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ ٩\nآیت میں’’اعمال‘‘ کو﴿ٱلسَّرَآئِرُ﴾یعنی راز کہنے میں ایک نکتہ ہے،وہ یہ کہ اعمال دل کے چھپے ہوئے رازوں کا نتیجہ ہوتے ہیں تو اب جس کا باطن نیک ہو اس کے اعمال بھی نیک ہوں گے تو اس کے راز قیامت کے دن اس کے چہرے پرنور،روشنی اور حیاء بن کر جھلکیں گے۔اس کے برخلاف جس کا باطن فاسد ہوتا ہے‘ اس کے اعمال بھی اس کے باطن کے تابع ہوتے ہیں اور اس کی صورت کا کوئی اعتبار نہیں ہوتااور اس کی باطنی گندگی اس کے چہرے پر تاریکی، وحشت اور شرمندگی بن کر ابھرے گی۔گرچہ دنیا میں ہمیں لوگوں کے ظاہری اعمال نظر آتے ہیں ان کا باطن ہم نہیں جان سکتے مگر قیامت کے دن لوگوں کے باطن کھل کر سامنے آجائیں گے تو اسی کے اعتبار سے حکم بھی لگے گا۔ (ابن القیم: ۳؍۲۸۸–۲۸۹)\nباطن کی اصلاح کی کیا اہمیت ہے؟\nفَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖ ١٠\nقیامت کے دن کافر کو کوئی قوت حاصل نہیں ہوگی جو اسے اللہ کے عذاب اور اس کی مضبوط گرفت سے بچاسکے اور نہ کوئی مددگار ہوگا جو اس کی مدد کرکے اسے اس آفت اوردکھ سے نجات دلاسکے۔حالانکہ یہی کافر دنیا میں اپنے خاندان اور قبیلے کی مدد سے دشمن سے بچ جایا کرتا تھا اور کسی ظالم یا حق چھیننے والے کے خلاف اپنے کسی حلیف کی مدد سے غلبہ پالیتا تھا۔(الطبری: ۲۴؍۳۵۹)\nقیامت کے دن بندے کو نہ کوئی قوت حاصل ہوگی اور نہ اس کا کوئی مدد گار ہوگا۔اس بات کو واضح کیجئے.\nإِنَّهُمۡ يَكِيدُونَ كَيۡدٗا ١٥ وَأَكِيدُ كَيۡدٗا ١٦\nاس سے سمجھ میں آجاتا ہے کہ کون غالب ہوگا! کیونکہ آدمی اس سے کہیں زیادہ کمزور اور حقیر ہے کہ مکمل علم رکھنے والے طاقتور اللہ پر غلبہ پاسکے۔ (السعدی؍۹۲۰)\nکافر اور گمراہ لوگ ہر آن اسلام اور مسلمانوں کے خلاف چالیں چلتے اورسازشیں کرتے رہتے ہیں۔اب اس آیت میں غور کرکے بتائیے کہ غالب کون ہوگا؟\nوَنُيَسِّرُكَ لِلۡيُسۡرَىٰ ٨\nہم آپ کے لئے اچھی باتیں اور نیک اعمال آسان کردیں گے اور آپ کو ایسی شریعت سے نوازیں گے جو آسان،عمدہ،بالکل سیدھی اور مبنی بر انصاف ہے، اس میں کوئی ٹیڑھاپن ہے،نہ تنگی اور نہ مشکل۔ (ابن کثیر: ۴؍۱۰۵)\nاس آیت کریمہ سے اسلام کے آسان اور بہترین دین ہونے کو واضح کیجئے.\nفَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ ٩\nنصیحت کیجئے جہاں وہ فائدہ مند ہو۔ اس سے علم سکھانے کا ایک ادب سمجھا جاسکتا ہے وہ یہ کہ جو علم کے لائق نہ ہو اسے علم نہ دیا جائے۔ابن مسعود رضی اللہ عنہ کہتے ہیں: آپ لوگوں سے ایسی کوئی حدیث بیان کریں جو اُن کی سمجھ میں نہ آئے تو یقینا وہ ان میں سے بہت سے لوگوں کے لئے فتنہ بن جاتی ہے۔ امیر المومنین علی رضی اللہ عنہ فرماتے ہیں: ’’لوگوں سے وہی بات کرو جنہیں وہ سمجھ سکتے ہوں کیا تم چاہوگے کہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم کو جھٹلایا جائے‘‘!۔ (ابن کثیر: ۴؍۵۰۱)\nاللہ تعالیٰ کا یہ فرمان: (إن نفعت الذکری) طالب ِعلم کا ایک ادب بتاتا ہے۔وہ کیا ہے؟\nفَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ ٩ سَيَذَّكَّرُ مَن يَخۡشَىٰ ١٠\nمفید نصیحت یہی ہے کہ آدمی پر اس نصیحت کا اثر ظاہر ہو،اگر کسی پسندیدہ چیز کے حصول کی نصیحت ہو تو آدمی اسے حاصل کرنے کی کوشش کرے اور اگر وہ نصیحت کسی تکلیف دہ چیز سے بچنے کی ہو تو آدمی اس سے بچے۔(ابن تیمیہ: ۶؍۵۰۲)\nآیت میں نصیحت کو ڈر کے ساتھ کیوں جوڑا گیا ہے؟\nwords\nالثَّاقِبُروشن / چمکتا ہوا.\nدَافِقٍجلدی سے رحم میں جم جانے والا.\nالصُّلبِپشت.\nوَالتَّرَائِبِسینے کی ہڈیاں.\nتُبلَى السَّرَائِرُامتحان لیا جائے گا؛ دل کی خفیہ باتوں کااظہار.\nرُوَيدًابہت کم.\nالمَرعَىسبز چارہ.\nغُثَاءًخشک چورا.\nأَحوَىبدلا ہوا/ متغیر ہونے والا."],[592,"§الأعلى ، الغاشيہ\ndeeds\nاذان کا جواب دیجئے،پھر اذان کے بعد کی دعا پڑھئے اور باجماعت نماز کی ادائیگی کے لئے مسجد میں پہنچئے.\nآپ کو دنیاکی زیب وزینت کی جو چیز اچھی لگتی ہے آپ اس میں سے تھوڑا ہی سہی، صدقہ کیجئے.\nکسی مسلمان کو اللہ تعالیٰ کی یاد دلائیے.\nguid\nاگر آپ کو کوئی چیز اچھی لگ رہی ہے لیکن وہ اللہ کو پسند نہ ہو تو اللہ کی پسند کو ترجیح دیجئے اور اپنی پسند چھوڑدیجئے.\nاقامت ِصلاۃ کا عظیم مقصد اللہ کا ذکر ہے تو آپ اس کا خصوصی خیال رکھئے.\nعمل کرنا اہم نہیں بلکہ اس میں اخلاص ہونا اور پھر اس کا قبول ہونا اہم ہے.\nrefl\nقَدۡ أَفۡلَحَ مَن تَزَكَّىٰ ١٤ وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ ١٥\nاللہ کے ذکر اور نماز سے پہلے تزکیہ کا ذکر کیا گیا ہے کیونکہ وہ ان تمام اعمال کی بنیاد ہے۔اس وجہ سے کہ اگر دل پاک ہوگا تو ہدایت کی کرنوں سے منور ہوگا،اس کے فوائد کو جانیگا اوران کے حصول کے لئے خوب جدوجہد کریگا۔(ابن عاشور: ۳۰؍۲۸۸)\nاللہ کے ذکر اور نماز سے پہلے تزکیہ کا ذکر کیوں کیا؟\nبَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ١٦\nدنیاوی زندگی کو ترجیح دینے کا معنی ہے اس سے راضی اورمطمئن ہوجانا اور آخرت سے بالکلیہ منہ موڑلینا۔(الالوسی: ۱۵؍۳۲۲)\nدنیاوی زندگی کو ترجیح دینے سے کیا مراد ہے؟\nوُجُوهٞ يَوۡمَئِذٍ خَٰشِعَةٌ ٢ عَامِلَةٞ نَّاصِبَةٞ ٣\n(خاشعة) مراد ہے ذلیل۔اللہ تعالیٰ نے براہ راست ذلیل نہ کہتے ہوئے ’’جھکے ہوئے‘‘ کہا۔یہ سختی کا اسلوب ہے جس سے یہ بتانا مقصود ہے کہ انہیں جب جھکنا چاہئے تھا تب تو انہوں نے ایسا نہیں کیا اور یہی حال “عمل کرنے والے“کا بھی ہے کہ انہیں جس وقت عمل کرنا چاہئے تھا تب نہیں کیا۔ (الالوسی: ۱۵؍۳۲۵)\nقیامت کے دن کافروں کو ﴿خَٰشِعَةً﴾اور ﴿عَمَلُهُۥ﴾کی صفت سے متصف کرنے سے کیا بتانا مقصود ہے؟\nفِي جَنَّةٍ عَالِيَةٖ ١٠\nجنت کو (عالیة) یعنی بلند کی صفت سے ذکر کرنے کا مقصد اس کے انتہائی حسن کا بیان ہے اس لئے کہ باغ جتنی بلند ی پر ہوگااتنا ہی خوبصورت ہوگا۔ (ابن عاشور: ۳۰؍۲۹۹)\nجنت کو ﴿عَلَيۡهِۚ﴾ یعنی بلند کیوں کہا گیاہے؟\nلَّا تَسۡمَعُ فِيهَا لَٰغِيَةٗ ١١\nجنت میں جو کلمات سنے جائیں گے وہ اللہ کی تعریف وتوصیف پر ہی مشتمل ہوں گے تاکہ جنتیوں کو ان کے عمدہ معانی کی لذت مل سکے او ر اس وجہ سے بھی کہ وہ دنیا والوں کی بیہودہ باتوں کو سن کر تکلیف محسوس کرتے تھے تو اس طرح ان کے دلوں سے اس تکلیف کا احساس بھی دور کردیا جائے۔(البقاعی:۲۲؍۹)\nدنیا کے لغو کے عوض جنت میں کیا ملے گا؟\nفِيهَا سُرُرٞ مَّرۡفُوعَةٞ ١٣\nاور اللہ کا یہ فرمان: (فیہا سرر مرفوعة):اس میں اونچے تخت ہوں گے،جنتیوں کی چارپائیاں اور تخت اونچے اونچے اس لئے ہوں گے تاکہ وہ جب ا ن پر بیٹھیں توان تمام نعمتوں اور اپنی ملکیت کو اچھی طرح دیکھ سکیں جن سے اللہ نے انہیں نوازاہوگا۔ (الطبری: ۲۴؍۳۸۷)\nاللہ تعالیٰ نے جنت کی چارپائیاں اور تخت اونچے اونچے کیوں بنائے ہیں؟\nأَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ ١٧\nاللہ نے اونٹوں کی پیدائش پر نظر ڈالنے پر ابھارا ہے کیونکہ اس میں بہت سے تعجب خیز امور ہیں مثلاً ان کےبہت طاقتور ہونے کے باوجود کمزور انسان بھی ان پر قابو پالیتا ہے اور وہ اس کے فرمانبردار بن جاتے ہیں،سخت پیاس برداشت کرنے کی قوت رکھتے ہیں اور ان میں انسانوں کے لئے بہت سے فائدے ہیں جیسے کہ ان کی سواری کرنا،ان پر بوجھ لادنا،ان کا گوشت کھانا اور ان کا دودھ اور پیشاب پینا وغیرہ۔ (ابن جُزی: ۲؍۵۶۶)\nاونٹوں کی خلقت کے کچھ عجائبات ذکر کیجئے.\nwords\nيَصلَى النَّاروہ اس آگ میں داخل کرے گا۔ جس کی گرمی بہت سخت ہوگی.\nعَامِلَةٌ نَاصِبَةٌعمل کرکرکے تھکے ہارے ہوئے.\nآنِيَةٍبہت سخت گرم.\nضَرِيعٍایک بہت گندی کانٹے دار نبات؛ جسے جانور نہیں چرتے.\nلاَغِيَةًایک لفظ بھی لغو نہیں ہوگا.\nمَوضُوعَةٌپینے والوں کے لیے تیار شدہ.\nوَنَمَارِقُتکیے.\nوَزَرَابِيُّ مَبثُوثَةٌاور گدے بچھے ہوئے.\nسُطِحَتبچھائی گئی."],[593,"§الفجر ، الغاشيہ\ndeeds\nنماز ِوتر ادا کیجئے.\nکوئی ہدیہ دے کر یا بھلی بات کرکے کسی یتیم کی عزت افزائی کیجئے.\nمال کا صدقہ دیاکیجئے اس سے آپ کے دل میں مال کی محبت کم ہوگی.\nguid\nذی الحجہ کے پہلے عشرہ کوخاص اہمیت حاصل ہے.\nاللہ کے فیصلہ اور تقدیر پر رضامندی مومنوں کی نشانی ہے.\nیتیموں اور مسکینوں کی تکریم کیجئے.\nrefl\nهَلۡ فِي ذَٰلِكَ قَسَمٞ لِّذِي حِجۡرٍ ٥\nحِجر کا معنی ہے عقل،سمجھ،فہم،دینداری اور فراست۔ عقل کو حِجر اس وجہ سے کہتے ہیں کہ وہ انسان کوغیر مناسب اقوال واعمال سے باز رکھتی ہے۔(ابن کثیر: ۴؍۵۰۸)\nمسلمان کے لئے عقل کی کیا اہمیت ہے؟\nوَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ ١٠\nمعنی یہ ہے کہ فرعون نے لاؤ لشکر، درباریوں اوراپنی سمجھ کے اعتبار سے ملک کو مضبوط بنانے والے مختلف اسباب اختیار کرکے اپنی بادشاہت کی جڑیں اتنی مضبوط کرلی تھیں گویا وہ کبھی ختم نہیں ہوگی۔ اس طرح اس کی حکومت بہت مستحکم ہوگئی تھی۔(البقاعی: ۲۲؍۳۰)\nفرعون کو (ذی الأوتاد) (مستحکم وپائیدار بادشاہت والا)کہا گیا اور پھر اس کی ہلاکت بیان کی گئی ہے۔یہ کس بات کی دلیل ہے؟\nفَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ ١٣\nعذاب کے لئے کوڑے کا لفظ استعمال کیا گیااس لئے کہ کوڑا مارنے میں تکرار کا وہ معنی پایا جاتا ہے جو تلوار وغیرہ میں نہیں ہے۔یہ بات ابن عطیہ رحمہ اللہ نے کہی ہے۔ علامہ زمخشری نے کہا ہے: کوڑے کا ذکر دنیاوی عذاب کی طرف اشارہ ہے کیونکہ دنیاوی عذاب آخرت کے عذاب سے بہت ہلکا ہے جیسے کہ کوڑے سے مارنا قتل کرنے سے ہلکا ہے۔(ابن جزی: ۲؍۵۶۹)\nعذاب کے لئے کوڑے کا لفظ استعمال کرنے میں بلاغت کے کون سے دونکتے ہیں۔بیان کیجئے.\nإِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ ١٤\nعبداللہ بن عباس رضی اللہ عنہما نے کہا: یعنی اللہ تعالیٰ سب کچھ دیکھ اور سن رہا ہے۔ وہ اپنے بندوں کے تمام اعمال پر نگراں ہے اور ہر ایک کو اس کے کئے کا دنیا اور آخرت میں بدلہ دیگا،پوری مخلوق اس کے سامنے پیش ہوگی تب وہ انصاف کے ساتھ سب کے درمیان فیصلہ کریگااور جو جس چیز کا مستحق ہوگا اس کے ساتھ ویسا ہی سلوک کریگا وہ ظلم سے پاک ہے۔(ابن کثیر: ۴؍۵۱۰)\nاللہ تعالیٰ سب اعمال کا نگراں ہے۔اس عقیدے سے آپ کو عملی طور پر کیا فائدہ ہوتا ہے؟\nفَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ ١٥\nکافر جو قیامت پر ایمان نہیں رکھتا اس کے نزدیک عزت اور ذلت کا معیار دنیاوی اسباب کی کثرت وقلت ہے۔مگر مومن کے نزدیک عزت یہ ہے کہ اللہ اسے اپنی اطاعت او ر خیر کی توفیق دے جو اسے آخرت کی کامیابی تک پہنچادے اور اگر اللہ اس کو دنیا میں سے کچھ عطاکرتا ہے تو وہ اللہ کی تعریف اور شکر ادا کرتا ہے۔(القرطبی: ۲۲؍۲۷۶)\nکیا اللہ کے نزدیک بندے کی عزت کا معیاریہ ہے کہ اسے دنیاوی حاصل ہوں؟\nفَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ ١٥ وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ ١٦ كَلَّاۖ\nاگر اللہ تعالیٰ کسی شخص کو آزمانے کی خاطر اس کے رزق میں کشادگی کرے اور آدمی اس سے یہ سمجھ بیٹھے کہ اللہ کی نظر میں اس کے معزز ہونے کی وجہ سے اللہ نے اسے نوازا ہے۔تو بات یہ نہیں بلکہ اللہ تعالیٰ اسے آزمانا اور جانچنا چاہتا ہے۔ اسی کے بالمقابل اگر اللہ تعالیٰ کسی کو جانچنے اور آزمانے کی خاطر اسے تنگ دستی میں مبتلا کردے تو وہ سمجھ بیٹھتا ہے کہ اللہ اسے ذلیل کررہا ہے۔ اللہ تعالیٰ ان دونوں کے باطل نظریے کی تردید کرتے ہوئے فرماتا ہے:﴿كُلِّ﴾ دونوں کا نظریہ غلط ہے،معاملہ ویسا ہرگز نہیں ہے جیسا وہ سمجھ رہے ہیں۔ اللہ تعالیٰ مال کسی کوبھی دے سکتا ہے جس سے محبت کرتا ہے اسے بھی اور جس سے نہیں کرتا اسے بھی۔اسی طرح تنگ دستی میں بھی دونوں کو مبتلا کرسکتا ہے۔حقیقت یہ ہے کہ دونوں حالتوں میں مدار اللہ کی اطاعت پر ہے کہ اگر مالدار ہو تو اللہ کا شکر ادا کرے او ر اگر مفلس ہوتو صبر کرے۔(ابن کثیر: ۴؍۵۱۰)\nآیات پر غور کرکے بتائیے کہ مالداری اور محتاجی کب نعمت ہوتے ہیں اور کب زحمت؟\nوَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ١٨\nتم دنیا کے اس قدر لالچی ہو اور اس کی محبت تمہارے دلوں میں اتنی مضبوطی سے جڑپکڑ چکی ہے کہ اس کے سبب تم ایک دوسرے کو فقیروں اورمسکینوں کو کھلانے پر نہیں ابھارتے ہو۔ (السعدی:۹۲۴)\nفقیروں اور مسکینوں کو کھانا کھلانے سے آدمی کو کون سی چیز روکتی ہے؟\nwords\nإِيَابَهُمموت کے بعد دوبارہ اٹھایا جانا.\nلِذِي حِجرٍعقل مند لوگوں کے لیے.\nإِرَمَقبیلہ ارم ؛ ان کے دادا کی طرف نسبت.\nذَاتِ العِمَادِقوت والے؛ اونچی عمارتیں.\nجَابُواکاٹ دیے.\nذِي الأَوتَادِوہ لشکری ؛ جو ملک کے ثبات میں کردار ادا کرتے ہیں.\nفَقَدَرَتنگ کیا.\nولاَ تَحَآضُّونَاور تم ایک دوسرے کو ترغیب نہیں دیتے.\nالتُّرَاثَمیراث.\nجَمًّابہت زیادہ."],[594,"§الفجر ، البلد\ndeeds\nیہ دعا پڑھاکیجئے:’’رَضِیْتُ بِاللہِ رَبًّا وَبِالْاِسْلَامِ دِیْنًا وَبِمُحَمَّدٍ صلی اللہ علیہ وسلم نَبِيًّاوَ رَسُوْلًا‘‘۔میں اللہ سے بطور رب،اسلام سے بطور دین اور محمد صلی اللہ علیہ وسلم سے بطور نبی ورسول راضی ہوں.\nاللہ سے حسن خاتمہ کی دعا کیجئے.\nاپنے بعض متعلقین کو اللہ کی اطاعت پر صبریااللہ کی نافرمانی سے بچنے پر صبر یا تقدیر پر صبر کرنے کی نصیحت کیجئے اور مخلوق کے ساتھ شفقت کا برتاؤ کرنے کی وصیت کیجئے.\nguid\nتنہائی اور محفل میں ہمیشہ اللہ کی نگرانی کا خیال رکھنا ضروری ہے.\nمکہ مکرمہ کی فضیلت اور اس کی بعض خصوصیات کا بیان.\nدنیا میں رہتے ہوئے ہمیشہ اپنے نفس سے جہاد کرتے رہنا چاہئے.\nrefl\nيَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي ٢٤\nگناہگار اپنے گناہوں پر شرمندہ ہوگا اور اطاعت گزار چاہیگا کہ کاش! اس نے اور زیادہ نیکیاں کرلی ہوتیں۔ (ابن کثیر: ۴؍۵۱۱)\nکیا قیامت کے دن صرف گناہگار ہی شرمندہ ہوگا؟وضاحت سے جواب دیجئے.\nيَٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ ٢٧ ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ ٢٨\nوہ دل جو اللہ کی بات پر اس طرح یقین رکھتا تھا کہ اس پر مطمئن تھا،اس کا یقین اتنا مضبوط تھا کہ شک کی کوئی گنجائش ہی نہیں تھی۔ یہ بھی کہا گیا ہے: مراد وہ مطمئن نفس ہے جسے اُس وقت کوئی خوف نہیں ہوگا۔(ابن جزی: ۲؍۵۷۲)\nنفس میں کون سی صفت ہے جس سے وہ اللہ کی رضا کی حقدار ہوتی ہے؟\nلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ ٤\nاس سے مراد وہ تکلیفیں اور مشقتیں ہیں جو انسان دنیا میں،برزخ میں جھیلتا ہے اور قیامت کے دن جھیلے گاچنانچہ انسان کے لئے یہی مناسب ہے کہ ایسے کام کرنے کی کوشش کرے جو اسے ان تکلیفوں سے نجات دلاسکیں اور اسے ہمیشہ کی خوشی اور سکون کا حقدار بناسکیں۔ اگر وہ ایسا نہیں کرتا ہےتو ہمیشہ ہمیشہ شدید عذاب میں ہی مبتلا رہے گا۔ (السعدی:۹۲۵)\nکیا مصیبتیں انسان کو صرف دنیوی زندگی میں ہی لاحق ہوتی ہیں؟اور وہ کون سے ذرائع اختیار کرکے اپنے آپ کو مصیبتوں سے نجات دلاسکتا ہے؟\nيَقُولُ أَهۡلَكۡتُ مَالٗا لُّبَدًا ٦\nشہوت پرستی اور گناہوں میں مال خرچ کرنے کو اللہ نے مال ہلاک کرنے سے تعبیر کیا ہے۔وجہ یہ ہے کہ ان جگہوں میں خرچ کرنے والا اپنے مال سے صحیح فائدہ نہیں اٹھاپاتا اور اسے اس خرچ کے عوض ندامت،نقصان،تھکاوٹ اور مال میں کمی کا خمیازہ بھی بھگتنا پڑتا ہے۔ (السعدی؍۹۲۵)\nگناہوں میں مال خرچ کرنے کوخرچ کرنے کے بجائے ’’مال ہلاک کرنا‘‘ کیوں کہا گیا ہے؟\nأَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ ٨ وَلِسَانٗا وَشَفَتَيۡنِ ٩ وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ ١٠\nان عظیم نعمتوں کا تقاضہ ہے کہ بندہ اللہ کے حقوق ادا کرے،اس کی نعمتوں پر شکربجالائے اور اس کی نافرمانی میں انہیں استعمال نہ کرے۔ (السعدی؍۹۲۵)\nآپ نے یہ جان لیا کہ اللہ تعالیٰ نے ہی آپ کو آنکھوں،زبان اور ہونٹوں کی نعمت سے نوازا ہے اور وہی ہے جس نے آپ کے لئے خیر و شر کے راستے کو واضح کیا تو اب ان نعمتوں کے تئیں آپ کا عملی اقدام کیا ہونا چاہئے؟\nفَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ ١١ وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ ١٢\nگھاٹی کہہ کر اس کے بعد مذکور نیک اعمال مراد لئے گئے ہیں اور انہیں پہاڑ کی گھاٹی سے تعبیر کرنے کی وجہ یہ ہے کہ ان کی انجام دہی مشکل ہے جیسے کہ پہاڑ پر چڑھنا مشکل ہوتا ہے۔(ابن جزی: ۲؍۵۷۴)\nاعمال صالحہ کو گھاٹی سے تعبیر کرنے میں کیاراز ہے؟\nيَتِيمٗا ذَا مَقۡرَبَةٍ ١٥\n(ذا مقربة) قرابت دار کو خصوصیت سے ذکر کرنے کی وجہ یہ بتانا ہے کہ اسے کھاناکھلانا دوسرے کو کھلانے سے زیادہ افضل اور اچھا ہے اور اسی معنی میں یہ حدیث ہے:’’ان الصدقۃ علی القریب صدقۃ وصلۃ، وعلی البعید صدقۃ فقط‘‘۔ رشتے دار کو صدقہ دیا جائے تو صدقہ اور صلہ رحمی دونوں ہوں گی اور غیررشتہ دار کو دیا جائے تو صرف صدقہ ہوگا۔(الشنقیطی: ۸؍۵۳۳)\nکھانا کھلانے میں قرابت دار یتیم کا خصوصی ذکر کیوں کیا گیا؟\nwords\nوَأَنَّى لَهُ الذِّكرَىاسے نصیحت فائدہ نہیں دے سکتی؛ اس کا وقت ختم ہو چکا.\nوَلاَ يُوثِقُاور نہیں باندھتا بیڑیوں میں.\nوَثَاقَهُاس کی طرح باندھنے جیسا.\nلاَ أُقسِمُمیں قسم اٹھاتا ہوں ۔ (لا : قسم کی تاکید کے لیے ہے).\nكَبَدٍمشقت / تھکاوٹ.\nلُبَدًابہت زیادہ.\nالعَقَبَةَآخری کی مشقت ؛ مال خرچ کرکے؛ اور نیک اعمال کرکے.\nمَسغَبَةٍبہت سخت بھوک.\nذَا مَترَبَةٍمعدوم ؛ جس کے پاس کچھ بھی نہ ہو."],[595,"§الشمس ، الليل ، البلد\ndeeds\nچاشت کی دورکعتیں پڑھا کیجئے.\nیہ دعا مانگئے:’’اَللّٰہُمَّ آت ِنَفْسِیْ تَقْوَاھَا وَزَكِّھَا اَنْتَ خَیرُ مَنْ زَکَّاھَا اَنْتَ وَلِیُّہَا وَمَوْلَاھَا‘‘۔اے اللہ!میرے دل کو تقویٰ سے نواز اور میرے نفس کو پاک وصاف کر بیشک تو ہی مجھے پاک وصاف کرنے پر قادر ہے تو ہی اس کا والی اور مالک ہے.\nیہ دعا مانگئے:’’اَللّٰہُمَّ اَلْہِمنِیْ رُشْدِیْ وَقِنِیْ شَرَّ نَفْسِیْ‘‘۔اے اللہ! مجھے ہدایت کی توفیق دے او ر مجھے اپنے نفس کے شر سے بچالے.\nguid\nسرکش کافروں پر اللہ کا عذاب بھی سخت ہوتا ہے.\nاپنے تزکیہ نفس اوراصلاح کا ہمیشہ خیال رکھنا چاہئے.\nاللہ تعالیٰ کا تقویٰ رکھتے ہوئے اس کی راہ میں خرچ کرنامعاملات کے آسان ہونے کا ایک سبب ہے.\nrefl\nوَنَفۡسٖ وَمَا سَوَّىٰهَا ٧\nانسانی نفس اللہ تعالیٰ کی نشانیوں میں سے ایسی بڑی نشانی ہے جو اس کی مستحق ہے کہ اللہ اس کی قسم کھائے۔یقینا وہ بہت باریک،ہلکی،تیزی سے نقل وحرکت کرنے والا،جلدی بدل جانے اور متاثر ہونے والا ہے،انسانی جذبات واحساسات جیسے فکر،ارادہ،مقصد،محبت اور نفرت کی آماجگاہ یہی ہے۔اگر نفس نہ ہوتا تو جسم صرف ایک بے فائدہ مورت کی مانند ہوتا اور اسے اس طور پردرست وہموار کردینا اللہ تعالیٰ کی بڑی نشانیوں میں سے ہے۔ (السعدی؍۹۲۶)\nاللہ تعالیٰ اپنی عظیم مخلوقات کی قسم کھاتا ہے۔ تو نفس میں کون سی عظمت ہے کہ اللہ نے اس کی قسم کھائی ہے؟\nفَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا ٨\nمحمدبن کعب رحمہ اللہ کہتے ہیں: اللہ عزوجل جب کسی بندے کے ساتھ خیر کا ارادہ کرتاہے تو اس کے دل میں خیر کا خیال ڈال دیتا ہے او روہ اسے کرلیتا ہے۔ اس کے برعکس کسی بندے کے ساتھ برائی کاارادہ کرتا ہے تو اس کے دل میں شر کا خیال ڈال دیتا ہے اور وہ اسے کربیٹھتاہے۔ (القرطبی: ۲۲؍۳۱۲)\nکیسے جانیں گے کہ اللہ نے کسی بندے کے ساتھ خیر کا یا شر کا ارادہ کیا ہے؟\nقَدۡ أَفۡلَحَ مَن زَكَّىٰهَا ٩ وَقَدۡ خَابَ مَن دَسَّىٰهَا ١٠\nجو شخص علماً اور عملاً ہر اعتبار سے اپنے نفس کو تقویٰ پر پروان چڑھائے اور بلندی تک لے جائے تو یقیناً وہ ہر مقصد میں کامیاب ہوگا اور ہر نقصان سے محفوظ رہے گا۔اس کے برخلاف جو جہالت اور گناہ کے ساتھ اپنے نفس کو گرائے اور ذلیل کرے تو وہ نقصان اٹھائیگا۔(الالوسی: ۱۵؍۳۶۱)\nانسانی نفس کی کامیابی کا کیا ذریعہ ہے؟\nفَكَذَّبُوهُ فَعَقَرُوهَا\nقوم کے سب سے بدبخت شخص نے اس اونٹنی کو قتل کیا۔اور یہاں سب کو قاتل اس لئے کہا گیا ہے کیونکہ وہ اس عمل سے راضی تھے۔ (القرطبی: ۲۲؍۴۱۲)\nقوم کے تمام لوگوں کو قاتل کیوں کہا گیا جبکہ قتل ایک ہی فرد نے کیا تھا؟\nوَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ ٣\nاللہ نے جانداروں میں نر اور مادہ دو جنس پیدا کرنے کی قسم کھائی ہے۔ اس میں اللہ کی کمال ِحکمت یوں ہے کہ وہ جن حیوانات کو باقی رکھنا چاہتا ہے ان میں نر اور مادہ دونوں جنس پیداکردی تاکہ ان حیوانات کی نسل آگے بڑھ سکے اور وہ باقی رہیں۔اللہ نے ان حیوانات میں توالد وتناسل باقی رکھنے کے لئے دونوں جنسوں میں ایک دوسرے کی طرف شہوانی جھکاؤ رکھ دیا اور دونوں کو ایک دوسرے کے مناسب بنادیا۔ (السعدی؍۹۲۷)\nجانداروں کو دوجنسوں میں پیدا کرنے میں اللہ سبحانہ وتعالیٰ کی کیا حکمت ہے؟\nفَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ ٥ وَصَدَّقَ بِٱلۡحُسۡنَىٰ ٦ فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ ٧\nاللہ تعالیٰ اس کے لئے آسان راستہ ہموار کرتا ہے یعنی اسے نیکیاں کرنے اور گناہوں سے بچنے کی توفیق دیتا ہے۔اس کی ضد مشکل راستہ کو ہموار کرنا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کا فرمان اسی معنیٰ میں ہے: ’’اعملوا فکل میسر لِما خلق لہ‘‘۔ عمل کرتے رہوکیونکہ ہر ایک جس کے لئے پیدا کیا گیا ہے اس تک پہنچانے والے اعمال اس کے لئے آسان کئے جاتے ہیں۔یعنی جو اس کے مقدر میں ہے وہ اس کے لئے ہموار کردیا جاتا ہے اور اللہ تعالیٰ اسی اعتبار سے اسے نیکیوں کی توفیق دیتایا شر کی طرف دھکیلتا ہے۔ (ابن جزی: ۲؍۵۸۹)\nاس آیت کی روشنی میں نبی صلی اللہ علیہ وسلم کے اس فرمان کی وضاحت کیجئے: ’’اعملوا فکل میسر لِما خلق لہ‘‘؟\nفَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ ٥ وَصَدَّقَ بِٱلۡحُسۡنَىٰ ٦ فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ ٧\nبعض سلف نے کہاہے: نیکی کا بدلہ اس طرح بھی ملتا ہے کہ اس کے بعد او ر نیکی کرنے کی توفیق ملتی ہے اور برائی کا بدلہ یہ بھی ہوتا ہے کہ آدمی اس کے بعد مزید برائی کرتا ہے۔(ابن کثیر: ۴؍۵۲۰)\nمذکورہ آیات کی روشنی میں سلف کے قول کی وضاحت کیجئے.\nwords\nمُؤصَدَةٌتہہ لگے ہوئے / بند.\nطَحَاهَااس کو بچھایا.\nدَسَّاهَاجس نے س کو گناہ سے نقصان پہنچایا.\nفَعَقَرُوهَااس کو نحر کردیا(کونچیں کاٹ ڈالیں).\nفَدَمدَمَپس ہلاکت ڈال دی ۔ انہیں سزا دی.\nتَجَلَّىاپنے نور سے منکشف ہوگیا.\nلَشَتَّىيقيناً مختلف ہے."],[596,"§الليل ، الضحى\ndeeds\nتھوڑا ہی سہی مگر ہمیشہ مال کا صدقہ دیا کیجئے.\nچاشت کی دورکعتیں پڑھا کیجئے.\nیتیم کی عزت کیجئے.\nguid\nاپنے نفس کے تزکیہ کی جانب خصوصی توجہ دیجئے.\nاللہ اور اس کے رسول صلی اللہ علیہ وسلم کو جھٹلانے والے کو اس کا کثیر مال عذاب سے نہیں بچاسکتا.\nکسی بھی عمل پر اللہ کے ثواب کی امید رکھئے،مخلوق کی پذیرائی کی توقع نہ رکھئے.\nrefl\nٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ ١٨ وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ ١٩\nآیت میں اس جانب رہنمائی ہے کہ متقی شخص کو مخلوق کا احسان نہیں لینا چاہئے اور اگر کسی وجہ سے ضرورت پڑجائے تو جلدہی اس کا بدلہ چکا دینا چاہئے تاکہ اس پر مخلوق میں سے کسی کا کوئی احسان نہ رہ جائے کہ اسے اس کا بدلہ دینے کی حاجت رہے تو اس طرح اس کے سارے اعمال اللہ کے لئے خالص ہوجائیں گے اور مخلوق کا بوجھ اتارنے کی ضرورت نہ رہے گی۔ (ابن القیم: ۳؍۳۲۶)\nمتقی شخص مخلوق کا احسان لینے کی بابت کیا موقف اختیار کرتا ہے اور کیوں؟\nوَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ ١٩ إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ ٢٠ وَلَسَوۡفَ يَرۡضَىٰ ٢١\nمتقی آدمی کسی کا احسان چکانے کے لئے خیر نہیں کرتا بلکہ ابتداء ً اللہ کے لئے پورے خلوص سے کرتا ہے۔(ابن جزی: ۲؍۵۸۰)\nاللہ تعالیٰ نے اس آیت میں مال خرچ کرنے والے کے لئے اپنی رضا ایک اہم شرط کے ساتھ مشروط بتائی ہے۔وہ کیا ہے؟\nمَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ ٣ وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ ٤\nحال یہ ہے کہ آخرت آپ کے لئے دنیا سے بہتر ہے اور آپ اسی کو دنیا پر ترجیح بھی دے رہے ہیں تو آپ کا رب بھی آپ کو چھوڑنہیں سکتا۔اس میں مومنوں کے لئے بندے کو رب سے قریب کرنے والی چیز کی طرف رہنمائی ہے اور کافروں کو اس بات پر پھٹکارا گیا ہے کہ وہ دنیا میں مکمل طور سے پھنسے اور آخرت سے منہ موڑے ہوئے ہیں۔(الألوسی: ۱۵؍۳۷۹)\nآیت میں غورکرکے واضح کیجئے کہ رب کی قربت چاہنے والے بندے میں کون سی صفت ہونی چاہئے.\nوَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ ١٠\nاس حکم میں مال کا سائل اور علم کا سائل دونوں داخل ہیں،اسی وجہ سے معلم طالب علم کے ساتھ اچھا سلوک کرنے،اس کی عزت کرنے اور اس کے ساتھ شفقت کا برتاؤ کرنے کا پابند ہے کیونکہ اس سے طالب علم کا اپنے مقصد تک پہنچنا آسان ہوتا ہے اور اس کی توقیر بھی ہوتی ہے جو بندوں او ر مخلوق کو نفع پہنچانے کے لئے تگ ودو کرتا ہے۔ (السعدی؍۹۲۸)\nکیا سائل کو جھڑکنے کی ممانعت مال کے سائل کے ساتھ خاص ہے؟واضح کیجئے.\nوَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ ١١\nاللہ کی نعمت کا بیان اس کے شکر کا باعث اور نعمت دینے والے سے محبت کرنے پر ابھارنے والا ہے اس لئے کہ لوگوں کے دلوں میں فطری طور سے احسان کرنے والے کی محبت ہوتی ہے۔(السعدی؍۹۲۹)\nاللہ کی نعمتوں کا بیان ایمان میں اضافہ کا ذریعہ کیسے ہوتا ہے؟\nوَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ ١١\nنعمت کا ذکر یعنی اس کا شکر ادا کرناہے اسی لئے بعض سلف نے یہ مستحب سمجھا ہے کہ اگر آدمی نے کوئی اچھائی کی ہو تو اسے بیان کرے جبکہ ریا ونمود اور گھمنڈ نہ ہو اور احساس ہو کہ دوسرے اس عمل میں اس کی اقتداکریں گے۔ (الألوسی: ۱۵؍۳۸۳)\nاللہ کی نعمتیں بیان کرنے کا حکم کیوں ہے؟\nأَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ ١\nخصوصیت سے سینہ کا ذکر کیا گیا کیونکہ وہی علوم ومعارف اور احساسات وادراکات جیسی مختلف نفسانی حالتوں کی جگہ ہے۔آیت سے مراد نبی صلی اللہ علیہ وسلم پر اللہ کی نعمت کا ذکر ہے کہ اس نے آپ کا سینہ کھول دیا اور کشادہ کیا جس کی وجہ سے آپ دعوت کے مشکل کام کو انجام دے سکے، نبوت کا بوجھ اٹھاسکے اور وحی کی حفاظت کرسکے۔(الشوکانی:۵؍۴۶۱)\nآیت کریمہ میں سینہ کو خصوصیت سے کیوں ذکر کیاگیا اور اس سے کیا مراد ہے؟\nwords\nلِلعُسرَىہر تنگی اور بد بختی کے لیے.\nوَمَا يُغنِياوراسے فائدہ نہ پہنچایا.\nتَرَدَّىجہنم میں گر گیا.\nإِنَّ عَلَينَا لَلهُدَىبے ہم پر ہے راہ ہدایت واضح کرنا(اپنے فضل و رحمت سی).\nتَلَظَّىبھڑکتی ہوئی روشن آگ.\nلاَ يَصلاَهَانہیں داخل کیا جائے گا اس میں.\nوَسَيُجَنَّبُهَااور اس سے دور کیا جائے گا.\nسَجَىجس نے کائنات کو اپنے اندھیرے سے ڈھانک لیا.\nوَمَا قَلَىوہ نہ بیزار ہوا؛ تاخیر وحی میں آپ سے بغض نہیں رکھا.\nفَآوَىآپ کو ٹھکانا دیا؛ آپ کا خیال رکھا.\nعَائِلًافقیر."],[597,"§الشرح ، العلق ، التين\ndeeds\nاپنے کسی خالی وقت کو عبادت سے پر کیجئے.\nشرعی علوم پر مشتمل کسی کتاب کے دوصفحات پڑھئے.\nاللہ سے دعا کیجئے کہ آپ کو نفع بخش علم دے او ر آپ کے علم میں اضافہ کرے.\nguid\nایمان اور عمل صالح اللہ کی نظروں میں بندے کی عزت بنائے رکھنے کا سبب ہیں.\nدینی احکام کے لئے سر جھکادینے اور انہیں قبول کرنے کی خواہش رکھئے.\nمسلمان کی زندگی میں پڑھنے کی خاص اہمیت ہے.\nrefl\nفَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا ٥ إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا ٦\nکلمہ(العسر) (سختی،مشکل) دوبار لایا گیا اور دونوں بار معرفہ ہی استعمال کیا گیا جس کا معنیٰ ہے کہ وہ ایک ہی ہے۔اس کے بالمقابل ﴿يُسۡرًا﴾ (آسانی) دونوں بار نکرہ ہی وارد ہوا ہے جس سے معلوم ہوا کہ وہ دو ہیں۔ نتیجہ یہ نکلا کہ سختی دو آسانیوں کے بیچ میں ہے:ایک ا س سے پہلے اور دوسری اس کے بعداور ایک سختی دوآسانیوں پر غالب نہیں آسکتی۔ (ابن القیم: ۳؍۳۳۳)\nان دوآیتوں پر غورکرکے واضح کیجئے کہ آسانی سختی سے بہت زیادہ وسیع ہے؟\nلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ ٤\nاس سے مراد انسان کا معتدل ہونا اور مضبوط جوان ہونا ہے۔ابوبکر بن طاہر رحمہ اللہ کہتے ہیں:اس کا مفہوم یہ ہے کہ اللہ نے انسان کو عقل سے مزین کیاہے، اوامر کی ادائیگی کی توفیق بخشی،خیر وشیر میں تمیز کی ہدایت دی،سیدھے قدوقامت والا بنایا اور وہ کھانا اپنے ہاتھ سے کھاتا ہے۔ اندر اور باہر سے اللہ کی سب سے حسین مخلوق ہے،اس کا جسم خوبصورت ہے،سر اور اس کے اندر کی چیزیں بہت بہترین انداز میں فٹ کی گئی ہیں،سینہ اپنے اندرونی اعضاء کے ساتھ بالکل مناسب ہے،پیٹ اپنے اعضاء کے ساتھ درست ہے،شرمگاہ اپنے آس پاس کی جگہوں کے ساتھ صحیح مقام پر ہے،دونوں ہاتھ اور ان کی پکڑ عمدہ ہے اور دونوں پیر ہر اعتبار سے جسم کا وزن اٹھانے کے لائق ہیں۔ (القرطبی: ۲۲؍۳۷۰–۳۶۸)\nانسان کی اچھی بناوٹ پر اللہ کے احسان جتانے کی کیا وجہ ہے؟ اور اس اچھائی کے انسانی جسم میں کیا نمونے ہیں؟\nثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ ٥\nاس آیت سے ابتداء ً یہی سمجھ میں آتا ہے کہ اس میں قیامت کے دن کافر کی حالت کی جانب اشارہ ہے اور وہ دنیا میں عمدہ اور حسین صورت میں ہونے کے بعد آخرت میں انتہائی بدصورت اور قبیح صورت والا ہوجائیگااسی سبب سے کہ اس نے اللہ کی نعمتوں کا شکر ادا نہیں کیا ہوگا۔ (الألوسی: ۳۰؍۱۷۶)\nانسان کو نچلے درجہ میں پہنچادینے کا کیا مفہوم ہے؟\nأَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ ٨\nاللہ تعالیٰ سب حاکموں سے بڑا حاکم ہے جو کسی پر ظلم وزیادتی نہیں کرتا،اس کے عدل کا تقاضہ ہے کہ قیامت قائم کرے اور دنیا میں جس نے ظلم کیا ہوگا اس سے مظلوم کا انتقام لے۔(ابن کثیر: ۴؍۵۲۹)\nیہ آیت دوبارہ زندہ کئے جانے اور بدلہ دیے جانے پر کس طرح دلالت کرتی ہے؟\nٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ٣ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ٤\nعلم سکھانے میں قلم کے ذریعہ لکھنے کو خصوصیت سے ذکر کرنے کی وجہ یہ ہے کہ اسی کے ذریعہ علوم ومعارف کو دوام حاصل ہوتا ہے اور دین ودنیا کی مصلحتیں محفوظ رکھی جاتی ہیں۔ (ابن جزی: ۲؍۵۹۰)\nآیت میں تعلیم کو قلم کے ساتھ مخصوص کرنے میں کیا راز ہے؟\nٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ٣ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ٤ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ ٥\nاللہ تعالیٰ کا کرم ہے کہ اس نے انسان کو وہ سب سکھایا جو وہ نہیں جانتا تھا،اللہ نے اسے علم کے ذریعہ عزت وشرف سے نوازا اور یہی وہ معیار ہے جس کے ذریعہ ہمارے والد آدم علیہ السلام فرشتوں پر ممتاز قرار پائے۔(ابن کثیر: ۴؍۵۳۰)\nوہ کون سی صفت ہے جس کی وجہ سے آدم علیہ السلام اوران کی اولاد تمام مخلوقات میں ممتاز قرار پائے؟\nكَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ ٦ أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ ٧ إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ ٨\nاللہ تعالیٰ انسان کے بارے میں بتارہا ہے کہ جب وہ مالدار ہوجاتا ہے اور دوسروں سے بے نیاز ہے تو اتراتا ہے،گھمنڈ کرتا ہے اور سرکشی پر اترآتا ہے۔پھر اللہ نے ایسے انسان کو ڈانٹتے،دھمکاتے اور نصیحت کرتے ہوئے فرمایا: (إن إلی ربک الرجعی) اللہ تعالیٰ کی جانب ہی تمہیں لوٹنا ہے اور اسی کے پاس تمہارا ٹھکانہ ہے اور وہ یقینا تم سے تمہارے مال کا حساب لیگا کہ تم نے اسے کہاں سے حاصل کیا اور کہاں خرچ کیا۔ (ابن کثیر: ۴؍۵۳۱)\nمالدار ہونے پر انسان پر کیا واجب ہوتاہے؟\nwords\nأَنقَضَبوجھل ہوا.\nفَرَغتَآپ فارغ ہوں (دنیا کی مصروفیات سے ).\nفَانصَبتو عبادت میں خوب محنت کر.\nفَارغَبمتوجہ ہو / طلب کر.\nوَطُورِ سِينِينَوہ پہاڑ جس پر موسی علیہ السلام اللہ تعاليٰ سے ہم کلام ہوئے.\nوَهَذَا البَلَدِ(یہ شہر )مکہ.\nتَقوِيمٍصورت.\nغَيرُ مَمنُونٍکم نہ ہونے والا؛ غیر مقطوع.\nعَلَقٍگاڑہے غلیظ خون کا لوتھڑا.\nالرُّجعَىواپسی ؛ ٹھکانا."],[598,"§العلق ، البينہ ، القدر\ndeeds\nیہ دعا مانگئے:’’اَللّٰہُمَّ خُذْ بِنَاصِيَتِیْ لِلْبِرّ وَالتَّقْوٰی‘‘۔اے اللہ!تو میری پیشانی پکڑ کر مجھے تقویٰ اور نیکی کی سمت لے چل.\nسجدۂ عبادت جیسے سجدۂ شکر،سجدۂ تلاوت یا نماز کے سجدوں کے ذریعہ اللہ کا قرب حاصل کیجئے.\nاپنے آس پاس والوں کو عبادت میں اخلاص کی اہمیت بتائیے.\nguid\nلیلۃ القدر کی فضیلت اور اس کی بعض برکتوں کا بیان.\nکتاب اللہ اور سنت رسول اللہ صلی اللہ علیہ وسلم پر اکٹھاہونے اور تفرقہ بازی سے دور رہنے کے لئے ہر ممکن کوشش کرنی چاہئے.\nتوحید کے بعد افضل اعمال میں سے: نماز ہے جو اللہ کا حق ہے اور زکاۃ ہے جو مخلوق کا حق ہے.\nrefl\nإِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ ١\nدن کے بجائے رات میں قرآن کا نزول یہ بتاتا ہے کہ رات کو خاص فضیلت حاصل ہے۔قرآن اور سنت میں اس کی اور مثالیں بھی موجودہیں: مثلاً اللہ تعالیٰ کا یہ فرمان:﴿سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا﴾ [الإسراء: ۱]، پاک ہے وہ ذات جو اپنے بندے کو راتوں رات مسجد حرام سے مسجد اقصیٰ تک لے گئی۔ یہ فرمان:﴿وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةً لَّكَ﴾ [الإسراء: ۷۹]،رات کے کچھ حصہ میں نماز تہجد میں قرآن پڑھئے،یہ آپ کے لئے زائد نماز ہوگی۔یہ فرمان: ﴿وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ﴾ [ق: ۴۰]، رات میں اللہ کی پاکی بیان کیجئے اور سجدوں کے بعد بھی۔یہ فرمان: ﴿إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡٔٗا وَأَقۡوَمُ قِيلًا﴾ [المزمل: ۶]، بے شک رات کا قیام نفس کو خوب کچل دیتا ہے اور قرآن سمجھنے کے لئے زیادہ مناسب وقت ہے۔ نیزیہ فرمان:﴿كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ﴾ [الذاریات: ۱۷]. وہ متقی لوگ راتوں کو بہت کم سوتے تھے۔ اور رسول اللہ صلی اللہ علیہ وسلم کا یہ فرمان:’’ینزل ربنا تبارک وتعالیٰ الی السماء الدنیا حین یبقی ثلث اللیل الآخر‘‘۔(متفق علیہ)جب رات کا آخری تیسرا پہر باقی رہتا ہے تو ہمارا رب تبارک وتعالیٰ آسمان ِدنیا پر نزول فرماتا ہے۔ یہ آیات واحادیث اس بات پر دلالت کرتی ہیں کہ رات میں بندوں کے لئے انوار وبرکات ِالٰہی اور فیضان ربی کا نزول زیادہ ہوتا ہے وہ اس وجہ سے کہ رات میں سکون ہوتا ہے،دن کی طرح مشغولیات نہیں ہوتیں،دنیا کی فکروں سے دل خالی ہوتا ہے او ر رات کا خوف بھی دل کی لگن اور صفائی میں زیادہ اثر انداز ہوتا ہے۔ (الشنقیطی: ۹؍۳۸)\nقرآن کو خصوصیت سے رات میں نازل کرنے کا سبب واضح کیجئے.\nإِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ ١\n(أنزلناہ)میں ضمیر قرآن کے لئے ہے، سیاق اس بات پر دلالت کرتا ہے۔ اس آیت میں تین وجوہ سے قرآن کی تعظیم کی دلیل ہے:پہلی وجہ:ضمیر کے ذریعہ اس کی طرف اشارہ کیا گیا ہے اس کا نام نہیں لیا گیایہ قرآن کی شہرت پر دلیل ہے اور اس بات کی غماز کہ نام لئے بغیربھی وہ معروف ہے۔ دوسری وجہ:اللہ نے قرآن کے نزول کے لئے افضل ترین وقت منتخب کیا۔ تیسری وجہ: اللہ نے اس کے نزول کو خود اپنی جانب منسوب کیا۔(ابن جُزی: ۲؍۵۹۳)\nآیت میں قرآن کی تعظیم کی کئی وجوہ ہیں۔بیان کیجئے.\nلَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ ١\nاس آیت میں اہل ِکتاب کے حد سے زیادہ ٹیڑھے ہونے کی دلیل ہے۔ وہ علم والے تھے توجاہل مشرکین کے مقابلہ میں ہدایت پر اکٹھا ہونا ان کے لئے زیادہ لائق تھا۔اس سے یہ بھی دلیل ملتی ہے کہ جاہل کی بہ نسبت عالم زیادہ ہٹ دھرم اور مخالفت میں سخت ہوتاہے۔(البقاعی:۲۲؍۱۹۲)\nسرزنش کرنے میں مشرکین سے پہلے اہل ِکتاب کو کیوں ذکر کیا گیا؟\nوَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ ٤\nسورت کی شروعات میں اہل کتاب کے ساتھ دوسروں کا بھی ذکر تھا مگر یہاں صرف اہل ِکتاب کو ذکر کیا گیا اس کی وجہ یہ ہے کہ وہ اپنی کتابوں میں ایسی آیات پڑھتے تھے جن میں نبی صلی اللہ علیہ وسلم کا تذکرہ تھا اس طرح وہ نبی صلی اللہ علیہ وسلم کی نبوت کی سچائی سے واقف تھے۔(ابن جزی: ۲؍۵۹۷)\nسورت کی شروعات میں اہل ِکتاب کے ساتھ دوسروں کا بھی تذکرہ ہے مگر یہاں صرف اہل ِکتاب کو ہی کیوں ذکر کیا گیا؟\nوَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ ٥\n(وما أمروا إلا لیعبدوا اللہ مخلصین لہ الدین حنفاء) یعنی شرک سے منہ موڑکر توحید کی طرف (ویقیموا الصلاة) نماز دین کی اشرف ترین عبادت ہے (ویؤتوا الزکاة) زکاۃ کا مقصد فقراء او ر حاجت مندو ں کے ساتھ احسان کرنا ہے (وذلک دین القیمة) یعنی مضبوط اور انصاف پر مبنی ملت ہے۔ یا درست اور معتدل ملت ہے۔ بہت سے ائمہ کرام رحمہم اللہ مثلاً زہری اور شافعی وغیرہ نے اس آیت سے دلیل پکڑی ہے کہ اعمال ایمان میں داخل ہیں۔ (ابن کثیر: ۴؍۵۴۰)\nیہ آیت کریمہ اہل سنت والجماعت کے اس مذہب پر کس طرح دلالت کرتی ہے کہ: ایمان دل سے تصدیق،زبان سے اقراراور اعضاء سے عمل کرنے کا نام ہے؟\nوَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ ٥\nنماز اور زکاۃ عبادت کے عام مفہوم میں داخل ہیں،اس کے باوجود خصوصیت سے ان کا تذکرہ ان کی فضیلت اور شرف کی وجہ سے ہے۔ اس میں یہ اشارہ ہے کہ جو اِن دونوں عبادات کو کما حقہ ادا کریگا وہ دین کے تمام احکام پر صحیح طور سے عمل پیرا ہوگا۔ (السعدی؍۹۳۲)\nعبادت کے مفہوم میں نماز اور زکاۃ کے داخل ہونے کے باوجود انہیں خاص طور سے کیوں ذکر کیا گیا؟\nوَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ\nاس میں دلیل ہے کہ عبادات میں نیت ضروری ہے اس لئے کہ اخلاص دل کا عمل ہے او ر وہ یہ ہے کہ عبادت کا مقصود صرف اللہ کی رضا ہو کچھ اور نہیں۔ (القرطبی:۲۲؍۲۱۴)\nوہ کون سا عظیم اصول ہے جس پر یہ آیت دلالت کررہی ہے؟\nwords\nلَنَسفَعًاہم اسے سختی سے لیں گے؛ پھر آگ میں پھینک دیں گے.\nنَادِيَهُأہل مجلس ؛ قوم کے لوگ.\nالزَّبَانِيَةَعذاب کے فرشتے.\nمُنفَكِّينَجدا ہونے والے(اپنے کفرکو چھوڑنے والے).\nكُتُبٌ قَيِّمَةٌ(قیمتی کتابیں ) سچی خبریں ؛ عادلانہ احکام."],[599,"§الزلزلہ ، البينہ ، العاديات\ndeeds\nجب کوئی نیک عمل کریں تو دل میں خیال کریں کہ جس جگہ آپ یہ عمل کررہے ہیں وہ جگہ قیامت کے دن آپ کے لئے گواہی دے گی.\nآج رات اپنے ہر اچھے اور برے عمل کا حساب کرلیجئے.\nاپنے مسلمان بھائی سے مسکرا کر ملئے اور راستہ سے تکلیف دہ چیزوں کو ہٹائیے۔ان کاموں میں مشقت بھی نہیں ہوتی اور ان کا اجر بھی بہت ملتا ہے.\nguid\nعمل صالح کرنے والے مومن ہی مخلوق میں سب سے اچھے ہیں.\nقیامت کی سخت ہولناکی کا بیان.\nموت کی اصل یہ ہے کہ وہ اچانک آنے والی ہے.\nrefl\nرَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ\nاللہ ان کی ہر تمنا اور خواہش پوری کردیگا کہ ان کی اور کوئی آرزو بچے گی ہی نہیں۔اور وہ یقین رکھیں گے کہ یہ سب خالص اللہ کا فضل ہے ورنہ اس پر کسی کا کوئی حق واجب نہیں ہوتا لیکن لوگ کما حقہ اللہ کی قدر نہیں کرتے۔اگر اللہ مخلوق کو اس کے گناہوں کے سبب پکڑلے تو سب کو ہلاک کردے۔ ان مومنوں پر اللہ کا سب سے بڑا احسان تو یہ ہوا کہ اس نے انہیں رسول اللہ صلی اللہ علیہ وسلم کی اتباع کی توفیق بخشی اور وہی ہر خیر کا ذریعہ ہے۔ (البقاعی: ۲۲؍۱۹۸)\nاللہ کا یہ فرمان (رضی اللہ عنہ ورضوا عنہ)کس امر پر دلیل ہے؟\nجَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ ٨\nاللہ کا ڈر حقیقی سعادت کی بنیاد اور بلند مرتبے کے حصول کی ضمانت ہے اس لئے کہ اگر اللہ کا ڈر نہ ہوتو کوئی گناہ اور نافرمانی سے رک نہیں سکتااور نہ اس دن کے لئے تیاری کرسکتا ہے جس دن مجرموں کی پیشانیوں اور پیروں کو پکڑ لیا جائیگا۔ (الالوسی: ۱۵؍۴۳۱)\nخشیت کاکیا معنی ہے؟\nجَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ ٨\nجو اپنے رب سے کما حقہ ڈریگا وہ ہر اس حرکت سے باز آجائیگا جو اللہ سبحانہ وتعالیٰ کے حضور نامناسب ہو۔اللہ کی آیات میں طعن کریگا اور نہ انہیں قبول کرنے سے ہچکچائے گا۔حق تو یہ ہے کہ اللہ کا ڈر دل سے نکل جائے تودل برباد ہوجاتا ہے۔(البقاعی: ۲۲؍۱۹۹)\nبندے کا اپنے رب سے ڈرنے کی کیا علامت ہے؟\nيَوۡمَئِذٖ تُحَدِّثُ أَخۡبَارَهَا ٤\nزمین اپنے اوپراچھائی اور برائی کرنے والوں کے حق میں یا ان کے خلاف گواہی دیگی کیونکہ زمین ان گواہوں میں شامل ہے جو بندوں کے اعمال کی گواہی دیں گے۔(السعدی؍۹۳۲)\nاس آیت سے آپ کو کون سا عملی فائدہ ہوتا ہے؟\nيَوْمَىِٕذٍ يَّصْدُرُ النَّاسُ اَشْتَاتًا لِّيُرَوْا اَعْمَالَهُمْۗ ٦\nقیامت کے دن ہر شخص اپنے کو ملامت کریگا اگر نیک ہوگا تواس وجہ سے کہ مزید نیکیاں کیوں نہ کیں؟اور اگر بدکار ہوا تو پچھتائیگا کہ کاش برائیاں نہ کی ہوتیں۔ یہ اس وقت ہوگا جب لوگ ثواب اور عذاب کو دیکھیں گے۔ عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: (أشتاتا) یعنی اپنے اعمال کے اعتبار سے الگ الگ۔ (القرطبی: ۲۲؍۴۳۷)\nکیا قیامت کے دن تمام لوگ اپنے آپ کو ملامت کریں گے؟ اور کیوں؟\nفَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ ٧ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ ٨\n﴿مِثۡقَالَ﴾یعنی وزن اور ﴿ذَرَّةٍۖ﴾چھوٹی چیونٹی کو کہتے ہیں۔ دیکھنایہاں آنکھوں سے دیکھنے کے معنی میں نہیں بلکہ بدلے کے معنی میں ہے اور اللہ نے چیونٹی کے وزن جتنا کہہ کر یہ بتایا ہے کہ اس سے زیادہ او ر بڑے کی جزا اور سزا بدرجہ اَولیٰ ملے گی گویا یوں کہا گیاکہ تھوڑا عمل ہو یازیادہ۔(ابن جزی: ۲؍۶۰۰)\nآیت میں﴿مِثۡقَالَ ذَرَّةٍۖ﴾ کہہ کر کیا مرادلیا گیا ہے؟\nفَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ ٧ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ ٨\nانس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:(اِن اللہ لا یظلم المؤمن حسنۃیثاب علیہا الرزق فی الدنیا ویجزی بہا فی الآخرۃ، وأما الکافر فیعطِیہ بہا فی الدنیا،فاذا کان یوم القیامۃ لم تکن لہ حسنۃ)۔اللہ تعالیٰ مومن کی کسی نیکی کو ضائع نہیں کرتا دنیامیں بھی اس پر نوازتا ہے اور آخرت میں بھی اس کا بدلہ دے گا لیکن کافر کوتو دنیا میں ہی اس کی ہر نیکی کا بدلہ دے دیتا ہے لہٰذا قیامت کے دن اس کے پاس کوئی نیکی نہیں ہوگی جس کا بدلہ مل سکے۔ (الطبری:۲۴؍۵۵۳)\nاللہ تعالیٰ عادل ہے کسی پر ظلم نہیں کرتاتو آخر ایسا کیوں ہوگا کہ کافر دنیا میں کی گئی اپنی نیکیوں کا آخرت میں کوئی بدلہ نہیں پائیگا؟واضح کیجئے.\nwords\nيَصدُرُ النَّاسُوہ مؤقف حساب سے واپس لوٹیں گے.\nأَشتَاتًامختلف گروہ.\nوَالعَادِيَاتِ ضَبحًاقسم ہے تیز دوڑتے گھوڑوں کی.\nفَالمُورِيَاتِ قَدحًاجو اپنے قدموں کی ٹاپوں سے آگ نکالتے ہیں.\nفَالمُغِيرَاتِ صُبحًاوہ جو صبح کے وقت حملہ آور ہوتے ہیں / غارت مچاتے ہیں.\nفَأَثَرنَپھر وہ اڑاتے ہیں.\nنَقعًاگرد / غبار.\nفَوَسَطنَ بِهِ جَمعًااپنے سواروں کے ساتھ دشمن کے لشکر کے وسط میں گھس جاتے ہیں."],[600,"§العاديات ، القارعہ ، التكاثر\ndeeds\nاپنی کوئی محبوب چیز صدقہ میں دیجئے.\nقیامت کے دن نیکیوں کا پلڑا بھاری کرنے کے لئے آج کچھ نیک اعمال کیجئے.\nقبرستان کی زیارت کے لئے جائیے بیشک یہ آخرت کی یاد دلاتی ہے.\nguid\nاللہ نے آپ کو کوئی نعمت دی ہو تو اس کے انکار یا ناشکری سے بچئے.\nدل کے اعمال کا اہتمام کیجئے.\nدنیاسے خبردار رہئے کہیں وہ آپ کو دین سے غافل نہ کردے.\nrefl\nإِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ ٦\n(إن الإنسان لربہ لکنود) یعنی انسان اپنے رب کا ناشکرا ہےجس نے نعمت کی ناشکری کی اس نے کفر کیا اور اس کاشکر ادا نہ کیا۔ مرادتمام انسان ہیں۔ معنی یہ ہے کہ انسان فطری طور پر ایسا ہی ہے سوائے اس کے جسے اللہ اپنے فضل وکرم اور توفیق سے بچالے۔(الالوسی: ۱۵؍۴۴۵)\nاکثر لوگ اللہ تعالیٰ کے شکر گزار نہیں ہیں۔یہ جاننے کے بعدآپ کیا موقف اختیار کریں گے؟\nوَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ ٨\nیعنی انسان مال سے شدید محبت رکھتا ہے۔مال کی محبت کی وجہ سے ہی وہ اپنے اوپر واجبی حقوق میں کوتاہی کرتا اور رب کے حق پر اپنی شہوت نفس کو مقدم کردیتا ہے۔ یہ دنیا کو سب کچھ سمجھ بیٹھنے اور آخرت سے غافل ہوجانے کے سبب ہوتاہے۔ (السعدی؍۹۳۳)\nمال سے شدید محبت انسان کے اخلاق پر کیسا اثر ڈالتی ہے؟\n۞أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ ٩ وَحُصِّلَ مَا فِي ٱلصُّدُورِ ١٠\nاللہ تعالیٰ نے قبر اور سینوں کو ایک ساتھ ذکر کیا ہے اس لئے کہ انسان کا سینہ اس میں موجود خیر وشر کو چھپاتا ہے اور قبر اس کے جسم کو چھپاتی ہے۔اللہ تعالیٰ اس کے جسم کو قبر سے اور راز کوسینہ سے نکال لیگا تواس کا جسم زمین پر ظاہر ہوگا او ر اس کا راز اس کے چہرے سے نمایاں ہوگا۔ (ابن القیم: ۲؍۳۵۲–۳۵۳)\nاللہ تعالیٰ نے ایک ہی سیاق میں قبر اور سینہ کو اکٹھا کیوں ذکر کیا ہے؟\nأَلۡهَىٰكُمُ ٱلتَّكَاثُرُ ١\nیہ خبر ہے۔ اس کا مقصد ڈانٹنا اور سرزنش کرنا ہے۔اور (ألہاکم) کا معنیٰ ہے کہ تمہیں غافل کردیا۔ اور ﴿ٱلتَّكَاثُرُ﴾کا معنی ہے: مال اور اولاد کی کثرت پر فخر کرنا، گویایہ لوگ کہتے ہیں: ہمارے پاس تم سے زیادہ ہے اور وہ لوگ کہتے ہیں ہمارے پاس تم سے زیادہ ہے۔نبی صلی اللہ علیہ وسلم نے اس سورت کو پڑھنے کے بعد فرمایا: ’’یقول ابن آدم مالی مالی،ولیس لک من مالک إلا ما أکلت فأفنیت،أولبست فأبلیت، أو تصدقت فأمضیت‘‘۔ (مسلم) انسان کہتا ہے میرا مال،میرا مال، حالانکہ اے انسان! تیرے کل مال میں سے تیرا صرف اتنا ہی ہے جو تو نے کھاکرختم کیا،یاپہن کر پراناکردیایا صدقہ دے کر اسے آگے بھیج دیا۔ (ابن جزی: ۲؍۶۰۵)\nخبر سے کیا معنی مراد ہے؟نیز کثرت کی چاہت کی بعض شکلیں ذکر کیجئے.\nأَلۡهَىٰكُمُ ٱلتَّكَاثُرُ ١\nاللہ نے اس چیز کا ذکر نہیں کیا جسے انسان دوسروں سے زیادہ حاصل کرنے کی حرص رکھتا اور اس پر فخر کرتا ہے۔تاکہ یہ جملہ ہر اس چیز کو شامل ہوجائے جسے لوگ دوسروں سے زیادہ حاصل کرنے کا لالچ رکھتے او ر اس پر فخر کرتے ہیں جیسے کہ مال،اولاد،مددگار،لاؤلشکر،خدام اور مان مرتبہ وغیرہ کہ جنہیں لوگ دوسروں سے زیادہ حاصل کرنے اور ان پر بڑائی جتانے کی چاہ رکھتے ہیں۔اس سے مقصود اللہ تعالیٰ کے لئے اخلاص نہیں ہے۔(السعدی؍۹۳۳)\nاللہ نے اس چیز کا ذکر کیوں نہیں کیا لوگ جسے دوسروں سے زیادہ حاصل کرنا اور ان پر فخر جتانا پسند کرتے ہیں؟\nحَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ ٢\nقتادہ رحمہ اللہ نے کہا: لوگ کہتے تھے:ہماری تعداد فلاں قبیلہ سے زیادہ ہے،ہمارا مال واسلحہ فلاں سے زیادہ ہے۔یہ لوگ اپنی بڑائی کے زعم میں دوسروں کو حقیر سمجھتے رہے حتی کہ سب کے سب قبروں میں جاسمائے۔(القرطبی: ۲۲؍۴۴۹–۴۵۰)\nانسان کے فخر وگھمنڈ کی انتہا کہاں ہوتی ہے؟\nثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ ٨\nانسان سے پوچھاجائیگا اس نے نعمت کا شکر ادا کیایا نہیں؟ معلوم ہوا کہ بندے پر اللہ کی نعمتوں کا شکر ادا کرنا واجب ہے۔ (ابن تیمیہ:۷؍۱۷۸)\nانسان نعمتوں کا حساب دینے سے کیسے بچ سکتا ہے؟\nwords\nلَكَنُودٌضرور نا شکرا ہے.\nلَشَهِيدٌاور وہ اپنی ناشکری کا گواہ بھی ہے.\nالخَيرِمال.\nبُعثِرَاسے نکالا گیا.\nالمَبثُوثِپھیلاہوا.\nكَالعِهنِمختلف رنگوں کی روئی کی طرح.\nالمَنفُوشِدھنکی ہوئی رنگین روئی.\nفَأُمُّهُ هَاوِيَةٌاس کا ٹھکانا/ جس میں وہ سر کے بل گرے گا.\nعِلمَ اليَقِينِسچا اور حقیقی علم.\nعَينَ اليَقِينِعین یقین (تم ضرور جہنم کو دیکھوگے ؛ بلا ریب )."],[601,"§الهمزہ ، الفيل ، العصر\ndeeds\nآپ نے کسی کی غیبت کی ہو یا کسی کی عیب جوئی کی ہو تو اس کا خیال کیجئے اور اللہ سے معافی مانگئے.\nاپنے مال میں سے کچھ صدقہ دیجئے.\nاپنے ساتھیوں کو بتائیے کہ کفار کتنے ہی جابر وسرکش کیوں نہ ہو جائیں یقینا ان کی مکاری ان کے ہی خلاف الٹنے والی ہے.\nguid\nوقت کی اہمیت جو آخرت کی کھیتی ہے.\nاچھے بھائی چارہ کی ایک علامت ایک دوسرے کو حق اور صبر کی تلقین کرنا ہے.\nمال سے دھوکا نہ کھائیں ورنہ وہ آپ کو اللہ کی عبادت سے غافل کردیگا.\nrefl\nوَٱلۡعَصۡرِ ١ إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ ٢ إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ ٣\nامام شافعی رحمہ اللہ کہتے ہیں:اگر لوگ اس سورت میں غوروفکر کریں تو یہ سب کے لئے کافی ہوجائے گی۔ اس کی تفصیل یو ں ہے کہ مراتب چار ہیں جو شخص بھی انہیں حاصل کرلے وہ کمالِ عروج پر پہنچ سکتا ہے: ۱)حق کو جاننا۔ ۲)حق پر عمل کرنا۔ ۳)اس کی تعلیم دینا ۔۴) اسے سیکھنے،اس پر عمل کرنے اور اسے سکھانے میں آنے والی مشکلات پر صبر کرنا۔ اللہ تعالیٰ نے یہ چاروں مراتب اس سورت میں ذکر فرمادیے ہیں۔ (ابن القیم: ۳؍۳۶۵)\nانسان کو اپنی اصلاح کے لئے جتنے وسائل کی ضرورت ہوتی ہے وہ سب اس سورت میں مذکورہیں۔وضاحت سے بتائیے.\nإِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ ٣\nلفظ(الصالحات) میں(ال) تعریف کے لئے ہے، یعنی یہ تمام نیک اعمال کو شامل ہے۔معنی یہ ہے کہ وہ شرعاً مطلوب تمام قسم کے نیک اعمال انجام دیتے ہیں۔ملحوظ رہے کہ نیک عمل کرنے کے معنی میں برا عمل چھوڑنا بھی داخل ہے۔ (ابن عاشور: ۳۰؍۵۳۲)\nکلمہ(الصالحات) میں (ال) کیوں داخل کیاگیا ہے؟\nإِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ\nپہلے دوکاموں یعنی ایمان اور عمل صالح سے آدمی اپنی ذات کی تکمیل کرتا ہے اور بعد کے دوکاموں یعنی حق اور صبر کی تلقین کرکے وہ دوسروں کی تکمیل کرتا ہے اور ان چاروں امور کو انجام دے کر ہی انسان نقصان سے محفوظ رہ کر عظیم فائدہ حاصل کرسکتاہے۔(السعدی؍۹۳۴)\nسورت میں خصوصیت سے انہی چار امور کو کیوں ذکر کیا گیا ہے؟\nوَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ ٣\n(وتواصوا بالصبر)صبر کی تلقین کرنے کا معنی یہ ہے کہ مصیبتوں،تقدیر کے فیصلوں اورجنہیں بھلائی کا حکم دیں اور برائی سے روکیں ان کی جانب سے پہنچائی جانے والی تکلیفوں پر صبر کرتے ہیں اور دوسروں کو بھی صبر کی نصیحت کرتے ہیں۔ (ابن کثیر: ۴/۵۵۱)\nحق کی تلقین کے بعد صبر کی تلقین کا جملہ لانے کا کیا فائدہ ہے؟اور ان دونوں کے درمیان کیا تعلق ہے؟\nٱلَّذِي جَمَعَ مَالٗا وَعَدَّدَهُۥ ٢\nمال جمع کرکے رکھنا اس وقت برا ہے جب اللہ کے راستے میں اور مخلوق کو فائدہ پہنچانے کی غرض سے خر چ نہ کیا جائے۔ (القرطبی: ۲۲؍۴۷۱)\nکیا ہر حال میں مال جمع کرنا براہے؟\nيَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ ٣\nآیت کا معنیٰ یہ ہے کہ ما ل کی محبت نے انہیں ایسا کردیا کہ وہ دنیا میں ہمیشہ رہنے کاگمان کرنے لگے تو جس طرح کوئی ہمیشہ کی زندگی سے محبت کرتا ہے اسی طرح وہ مال سے محبت کرنے لگے اور شہوت پرستی و فانی تعیش پسندی میں خوب آگے بڑھنے لگے اس شخص کی طرح جو یہ سمجھ بیٹھا ہو کہ اسے موت نہیں آئیگی۔ اس میں دراصل اشارہ ہے کہ صرف اعمال صالحہ ہی ہیں جو آدمی کو آخرت میں ہمیشہ کی زندگی کا عیش دلواسکتے ہیں۔ (البقاعی: ۲۲؍۲۴۵)\nمال کی حد سے زیادہ محبت انسان کے خیالات اور نظریات پر خطرناک اثر ڈالتی ہے۔اس پر روشنی ڈالئے.\nٱلَّتِي تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ ٧\nدل کو خصوصیت سے ذکر کیا گیا حالانکہ جہنم کی آگ پورے جسم کو جلائیگی۔اس کی وجہ یہ ہے کہ دل ہی غلط عقائد کا گھر ہوتا ہے، یایہ کہ گناہ جب دل تک پہنچ جائیں تو انسان کے جیتے جی اس کا دل مرجاتا ہے۔یعنی زندہ رہتے ہوئے ان کی حالت مردوں کی طرح ہوجاتی ہے۔ (الشوکانی: ۵؍۴۹۴)\nجہنم کی آگ پورے جسم کو جلائیگی تو پھر خاص طور سے دل کو کیوں ذکر کیا گیا؟\nwords\nهُمَزَةٍغیبت کرنے والا.\nلُمَزَةٍلوگوں پر طعنہ زنی کرنے والا.\nوَعَدَّدَهُاسے گنتا رہا.\nلَيُنبَذَنَّوہ ضرور پھینکا جائے گا.\nالحُطَمَةِوہ آگ جو ہر چیز کو چورا بنادے گی.\nتَطَّلِعُ عَلَى الأَفئِدَةِوہ ان کے دلوں تک چڑھ جائے گی (اپنی شدت کی وجہ سے).\nمُؤصَدَةٌبند کی ہوئی.\nفِي عَمَدٍ مُمَدَّدَةٍلمبے لمبے ستونوں میں (انہیں عذاب دیا جائے گا).\nأَبَابِيلَایک دوسرے کے پیچھے مختلف جماعتیں."]])